const COLLECTORS = {
  async commits(gh, ctx) {
    const commits = await windowCommits(gh, ctx.repo, ctx.defaultBranch, ctx.sinceIso);
    return {
      list: commits,
      count: commits.length,
      substantiveChange: commits.some((c) => c.substantive),
      touchedPaths: [...new Set(commits.flatMap((c) => c.files))],
    };
  },

  async prs(gh, ctx) {
    const open = await paged(gh, `/repos/${ctx.repo}/pulls?state=open&sort=updated&direction=desc`);
    const since = new Date(ctx.sinceIso);

    // PRs MERGED during the window, in a field of their OWN. A merged PR carries
    // the review discussion and the "what changed and why" — usually the richest
    // lesson material in a window — and `state=open` alone made it unreachable to
    // any task bound to this signal. It is deliberately NOT folded into `open` or
    // `touched`: those two are other tasks' target sets (the PR tidy sweep acts on
    // `open`), and widening them here would silently widen what those tasks do.
    // The same exclusions the `commits` and `issues` collectors apply hold here, so
    // a growth task still cannot see its own merged output and re-trigger on it.
    const closed = await pagedWindow(
      gh,
      `/repos/${ctx.repo}/pulls?state=closed&sort=updated&direction=desc`,
      (p) => new Date(p.updated_at) >= since,
    );
    const mergedCandidates = closed.filter((p) => p.merged_at && new Date(p.merged_at) >= since && isMinablePr(p));

    // WHICH OF THE WINDOW'S PRs A SCHEDULED TASK WROTE, read structurally rather
    // than off its title: one commit read per PR that moved in the window, for its
    // head's `Claudinite-Task:` trailer (task-trailer.mjs). This is what makes the
    // silence gate hold for a task added tomorrow — a title regex has to learn
    // each new task's name, and only ever learns it after that task re-armed a
    // neighbour with its own output.
    //
    // Scoped to the window's PRs, never the whole open set: `open` is other tasks'
    // TARGET set (the PR tidy sweep acts on it, the pending-round conditions read
    // its paths), and only MOVEMENT is what the trailer reclassifies.
    const inWindow = open.filter((p) => new Date(p.updated_at) >= since);
    const taskAuthored = new Map();
    for (const p of [...inWindow, ...mergedCandidates]) {
      if (taskAuthored.has(p.number)) continue;
      const sha = p.head?.sha;
      if (!sha) { taskAuthored.set(p.number, false); continue; }
      const head = await gh(`/repos/${ctx.repo}/commits/${sha}`);
      // An unreadable head is UNKNOWN, and unknown is not task-authored: a PR a
      // person opened must never be classified as machinery over a failed read.
      taskAuthored.set(p.number, head.status === 200 && taskFromMessage(head.json?.commit?.message ?? '') !== null);
    }

    const merged = mergedCandidates
      .filter((p) => !taskAuthored.get(p.number))
      .map((p) => ({ number: p.number, title: p.title, mergedAt: p.merged_at }));

    // Each open PR's changed paths — the pending work itself, so a precondition
    // can rule on WHAT is waiting for review rather than on a marker somebody has
    // to remember to apply (wiki-growth declines while a `product-wiki/` change is
    // pending). One read per open PR: the open set is a handful, and no PR listing
    // carries files.
    //
    // `null` is UNKNOWN, and it is a third state, not an empty list: every PR
    // changes at least one file, so an empty read is a read that failed, and a
    // precondition gating on a path must decline on "I could not look" rather than
    // read it as "nothing pending".
    const withPaths = [];
    for (const p of open) {
      // Capped at PR_FILE_PAGES: past it a PR is a mass refactor, whose paths no
      // consumer of this signal rules on, and paying 30 reads for one would be the
      // window's whole budget.
      const files = await paged(gh, `/repos/${ctx.repo}/pulls/${p.number}/files`, PR_FILE_PAGES);
      const changedPaths = files.map((f) => f.filename).filter(Boolean);
      withPaths.push({
        number: p.number, title: p.title, updatedAt: p.updated_at,
        changedPaths: changedPaths.length ? changedPaths : null,
      });
    }

    return {
      open: withPaths,
      touched: inWindow.filter((p) => !taskAuthored.get(p.number)).map((p) => p.number),
      merged,
    };
  },

  async issues(gh, ctx) {
    const open = await paged(gh, `/repos/${ctx.repo}/issues?state=open&sort=updated&direction=desc`);
    const since = new Date(ctx.sinceIso);
    // Exclude PRs (the issues endpoint returns both) and the scheduler's own
    // work items, its schedule board, and standing trackers — invisible to
    // signals (DESIGN §3.3). The board especially: every rewrite would land in
    // `issues.touched` and wake tidy-issues on the queue's own churn (F8).
