    argName: 'path-prefix',
    holds(s, { arg }) {
      const outside = touchedPaths(s).filter((p) => !p.startsWith(arg));
      return outside.length
        ? {
          holds: true,
          reason: `${outside.length} path(s) outside ${arg} changed in the window`,
