1	import { finding } from '../../../engine/checks/helpers/findings.mjs';
2	// Namespace-imported and guarded for the same reason legacy-shape-in-use is: a
3	// member's pack lane and engine lane converge on separate cycles, and this pack
4	// can sit beside a task-contract that predates either export.
5	import * as contract from '../task-contract.mjs';
6	import * as calendar from '../calendar.mjs';
7	import * as declarationText from '../task-declaration-text.mjs';
8	
9	// THE ADVISORY HALF OF THE TASK CONTRACT'S FIELD TOLERANCES. `normalizeTaskDeclaration`
10	// accepts two generations of field names, the retired one-word outcome ceilings
11	// and the retired `frequency` field (which reads as the cadence term it always
12	// meant, tasks-dispatch DESIGN §5), so a task declared in the oldest vocabulary
13	// runs exactly like one declared today — and nothing told its author that the
14	// acceptance ends a convergence window after this advisory ships (#1642, #1725).
15	//
16	// It reads the declaration SOURCE rather than the normalized object, because by
17	// the time anything holds a task declaration the legacy spelling is gone: the
18	// door normalizes at load, which is what makes the tolerance invisible.
19	// Matching is therefore textual and deliberately conservative — a top-level key
20	// line in a task declaration — so the finding always points at a line an author
21	// can edit. Both declaration forms are read, and one pattern covers both: the
22	// key is bare in the module form and quoted in the JSON, and the value quote is
23	// whichever that file uses.
24	//
25	// ADVISORY: the old spelling works, and a task file is a member's own content.
26	const TASK_FILE = /(^|\/)tasks\/[^/]+\/task\.(json|mjs)$/;
27	const isTaskFile = (path) =>
28	  (typeof declarationText.isTaskDeclarationPath === 'function'
29	    ? declarationText.isTaskDeclarationPath(path)
30	    : TASK_FILE.test(path));
31	
32	const rule = {
33	  id: 'legacy-task-fields',
34	  severity: 'advisory',
35	  since: '2026-09-03',
36	  description: 'Task declarations name their fields and outcome in the current vocabulary',
37	  why: 'the contract accepts two retired generations of field names, two retired generations of outcome ceilings and the retired frequency field for one convergence window after this advisory ships (#1642, #1725) — nothing counts who is still on them, so a declaration not renamed inside that window simply stops being read',
38	
39	  run(ctx) {
40	    const fields = contract.LEGACY_FIELDS ?? {};
41	    const outcomes = contract.LEGACY_OUTCOMES ?? {};
42	    const ceilings = contract.LEGACY_CEILINGS ?? {};
43	    const names = Object.keys(fields);
44	    if (names.length === 0 && Object.keys(outcomes).length === 0 && Object.keys(ceilings).length === 0) return [];
45	
46	    const fieldRe = names.length ? new RegExp(`^\\s*"?(${names.join('|')})"?\\s*:`) : null;
47	    const outcomeRe = /^\s*"?expected_outcome"?\s*:\s*['"]([^'"]+)['"]/;
48	    // The cadence field, retired into the expression. Guarded on the engine
49	    // exporting the term spelling: beside an older calendar the field is not a
50	    // tolerance yet, and reporting it would ask for an edit that engine rejects.
51	    const frequencyRe = typeof calendar.cadenceTermFor === 'function' ? /^\s*"?frequency"?\s*:\s*['"]([^'"]+)['"]/ : null;
52	
53	    const out = [];
54	    for (const file of ctx.files.filter(isTaskFile)) {
55	      const text = ctx.read(file);
56	      if (text === null) continue;
57	      text.split('\n').forEach((text_line, i) => {
58	        const field = fieldRe?.exec(text_line);
59	        if (field) {
60	          out.push(finding(rule, {
61	            file,
62	            line: i + 1,
63	            what: `declares the retired field \`${field[1]}\``,
64	            fix: `rename it to \`${fields[field[1]]}\` — the contract maps every retired spelling straight to today's name, so this is a one-line edit with no behaviour change`,
65	          }));
66	        }
67	        const frequency = frequencyRe?.exec(text_line);
68	        if (frequency) {
69	          const term = (calendar.ACCEPTED_FREQUENCIES ?? []).includes(frequency[1]) ? calendar.cadenceTermFor(frequency[1]) : 'due:<daily|weekly|monthly>';
70	          out.push(finding(rule, {
71	            file,
72	            line: i + 1,
73	            what: 'declares the retired field `frequency`',
74	            fix: `write it as the first condition — \`"preconditions": ["${term}", …]\` — and drop a \`"none"\` beside it; the field reads as exactly that today, and the nightly update rewrites a member's own task files`,
75	          }));
76	        }
77	        const outcome = outcomeRe.exec(text_line);
78	        if (outcome && Object.hasOwn(outcomes, outcome[1])) {
79	          out.push(finding(rule, {
80	            file,
81	            line: i + 1,
82	            what: `declares the retired outcome ceiling \`${outcome[1]}\``,
83	            fix: `write \`expected_outcome: 'fresh_pr'\` with \`automerge: '${outcomes[outcome[1]]}'\` beside it — the one word always meant that pair, and spelling it out is what lets the policy be narrowed later`,
84	          }));
85	        } else if (outcome && Object.hasOwn(ceilings, outcome[1])) {
86	          out.push(finding(rule, {
87	            file,
88	            line: i + 1,
89	            what: `declares the retired outcome ceiling \`${outcome[1]}\``,
90	            fix: `write \`expected_outcome: '${ceilings[outcome[1]]}'\` — the word it became, in the vocabulary that also says amend_existing_or_create_new_pr and supersede_existing_pr`,
91	          }));
92	        }
93	      });
94	    }
95	    return out;
96	  },
97	};
98	
99	export default rule;

