// THE ITEM'S OWN FACTS, as a precondition term sees them (DESIGN §16.4, §5): the
// body's fields plus the two the terms read that are not fields — the issue number,
// and whether somebody created or woke this item. `woken` is true for an item
// stamped by a lever AND for one born ad-hoc (a marked issue, a chain link): both
// exist only because somebody asked, which is what the `woken` term and the cadence
// terms need to know, and neither is the scheduler's own ask.
export function itemFacts(item) {
  if (!item) return null;
  const fields = parseWorkItemBody(item.body);
  return {
    ...fields,
    number: item.number ?? null,
    woken: fields.woken !== null || originOf(item) === ORIGIN_AD_HOC,
  };
}

