6	// The run-history terms (tasks-dispatch DESIGN §5): a task's cadence, its view of
7	// its own last failure, and whether it runs only when somebody asks — every one a
8	// condition over the `runs` signal, the task's own unqualified work items newest
9	// first, read at every scheduler tick. Pure over that bundle, so each case here is
10	// the real evaluator against a hand-built history at a chosen instant.
11	
12	const SCHEDULE = { dailyHour: 4, weeklyDay: 'Sun', monthlyDay: 1 };
13	const NOW = '2026-09-09T16:20:00Z'; // a Wednesday; today's daily anchor is 04:00Z, the weekly one Sunday the 6th
14	const run = (over = {}) => ({
15	  number: 10, createdAt: '2026-09-08T04:05:00Z', closedAt: '2026-09-08T04:40:00Z', state: 'closed',
16	  status: 'task:status:done', park: null, outcome: 'done', ...over,
17	});
18	const runs = (...list) => ({ runs: { list, horizonDays: 40 } });
19	const evaluate = (preconditions, signals, over = {}) =>
20	  evaluatePreconditions({ preconditions, signals, schedule: SCHEDULE, now: NOW, windowDays: 1.05, ...over });
21	
22	// --- due:<cadence> ------------------------------------------------------------
23	
24	test('due:daily holds only while no run of the task started or ended since today\'s anchor', () => {
25	  assert.equal(evaluate(['due:daily'], runs()).run, true, 'no run at all');
26	  assert.equal(evaluate(['due:daily'], runs(run())).run, true, 'yesterday\'s run is before today\'s 04:00 anchor');
27	  const today = run({ createdAt: '2026-09-09T04:05:00Z', closedAt: '2026-09-09T04:30:00Z' });
28	  assert.equal(evaluate(['due:daily'], runs(today)).run, false, 'a run since the anchor consumed today');
29	  // Both halves of the occurrence guard (F13): an item CREATED before the anchor
30	  // that CLOSED after it ran today, and a second one today is a double execution.
31	  const straddling = run({ createdAt: '2026-09-09T03:50:00Z', closedAt: '2026-09-09T04:10:00Z' });
32	  assert.equal(evaluate(['due:daily'], runs(straddling)).run, false);
33	  assert.match(evaluate(['due:daily'], runs(today)).reason, /already ran since/);
34	});
35	
36	test('due:weekly and due:monthly anchor on the repo\'s own schedule', () => {
37	  const lastWeek = run({ createdAt: '2026-09-05T04:05:00Z', closedAt: '2026-09-05T05:00:00Z' });
38	  const thisWeek = run({ createdAt: '2026-09-07T04:05:00Z', closedAt: '2026-09-07T05:00:00Z' });
39	  assert.equal(evaluate(['due:weekly'], runs(lastWeek)).run, true);
40	  assert.equal(evaluate(['due:weekly'], runs(thisWeek)).run, false);
41	  assert.equal(evaluate(['due:monthly'], runs(lastWeek)).run, false, 'the 5th is after the 1st');
42	  const lastMonth = run({ createdAt: '2026-08-20T04:05:00Z', closedAt: '2026-08-20T05:00:00Z' });
43	  assert.equal(evaluate(['due:monthly'], runs(lastMonth)).run, true);
44	  // A member anchored elsewhere moves every cadence with it.
45	  const late = { ...SCHEDULE, dailyHour: 20 };
46	  assert.equal(evaluate(['due:daily'], runs(run({ createdAt: '2026-09-09T04:05:00Z', closedAt: '2026-09-09T05:00:00Z' })), { schedule: late }).run, false,
47	    'at 16:20 the most recent 20:00 anchor is yesterday evening\'s, and this morning\'s run came after it');
48	  assert.equal(evaluate(['due:daily'], runs(run({ createdAt: '2026-09-08T19:00:00Z', closedAt: '2026-09-08T19:30:00Z' })), { schedule: late }).run, true,
49	    'a run before yesterday evening\'s anchor leaves this period open');
50	});
51	
52	test('a run still open counts — an item that started since the anchor is this period\'s', () => {
53	  const open = run({ createdAt: '2026-09-09T04:05:00Z', closedAt: null, state: 'open', status: 'task:status:needs-human-failure', park: 'failure', outcome: null });
54	  assert.equal(evaluate(['due:daily'], runs(open)).run, false);
55	});
56	
57	test('a woken item satisfies the cadence terms — the wake IS the cadence', () => {
58	  const today = run({ createdAt: '2026-09-09T04:05:00Z', closedAt: '2026-09-09T04:30:00Z' });
59	  const woken = { item: { number: 11, woken: true } };
60	  assert.equal(evaluate(['due:daily'], runs(today), woken).run, true);
61	  assert.equal(evaluate(['last-run-over:7d'], runs(today), woken).run, true);
62	  assert.match(evaluate(['due:daily'], runs(today), woken).reason, /woken/);
63	  // …and nothing else: a woken item still answers to the task's other conditions.
64	  assert.equal(evaluate(['due:daily', 'substantive-change'], { ...runs(today), commits: { substantiveChange: false } }, woken).run, false);
65	});
