67	test('due takes exactly one of the three cadences', () => {
68	  assert.match(evaluate(['due:hourly'], runs()).error, /"due" takes one of daily, weekly, monthly/);
69	  assert.match(evaluate(['due'], runs()).error, /takes an inline argument/);
70	  const problems = validatePreconditions(['due:fortnightly']);
