78	  // math has always read the defaults for it (04:00Z daily, Sunday, the 1st).
79	  assert.equal(evaluate(['due:daily'], runs(run({ createdAt: '2026-09-09T04:05:00Z', closedAt: '2026-09-09T04:30:00Z' })), { schedule: null }).run, false);
80	  assert.match(evaluate(['due:daily'], runs(), { now: null }).error, /no instant/);
81	});
