91	  assert.equal(evaluate(['last-run-over:7d'], runs(run())).run, false);
92	  assert.match(evaluate(['last-run-over:7d'], runs(run())).reason, /started .* ago/);
93	  // Newest first is the collector's promise; the term reads the head of the list.
94	  const older = run({ number: 3, createdAt: '2026-08-01T04:05:00Z', closedAt: '2026-08-01T05:00:00Z' });
95	  assert.equal(evaluate(['last-run-over:7d'], runs(run(), older)).run, false);
96	});
