77	  for (const item of items) {
78	    const body = parseWorkItemBody(item.body);
79	    for (const target of body.blockedBy) edges.push({ from: item.number, to: target, kind: 'blocked-by' });
80	    if (body.endsWhen) edges.push({ from: item.number, to: body.endsWhen, kind: 'ends-when' });
81	  }
82	  for (const pr of prs) {
83	    if (pr.closesIssue) edges.push({ from: `pr:${pr.number}`, to: pr.closesIssue, kind: 'closes' });
