88	// The connected components of that graph. A lone node is a component of one, which is
89	// what lets a plain issue nobody links to still be a row when it earns one.
90	export function componentsOf(nodes, edges) {
91	  const parent = new Map(nodes.map((n) => [n, n]));
92	  const find = (n) => {
93	    if (!parent.has(n)) parent.set(n, n);
94	    while (parent.get(n) !== n) { parent.set(n, parent.get(parent.get(n))); n = parent.get(n); }
95	    return n;
96	  };
97	  const union = (a, b) => { const ra = find(a); const rb = find(b); if (ra !== rb) parent.set(ra, rb); };
98	  for (const e of edges) { if (parent.has(e.from) || parent.has(e.to)) union(e.from, e.to); }
99	  const groups = new Map();
100	  for (const n of nodes) {
101	    const root = find(n);
102	    if (!groups.has(root)) groups.set(root, []);
103	    groups.get(root).push(n);
104	  }
105	  return [...groups.values()];
106	}
