110	// An item's PREDICTED time, and why it is there. This is the board's single most
111	// load-bearing derivation, so each branch names the field it read:
112	//
113	//   a stamped `Not-before`     → that instant. The stamp IS the schedule.
114	//   blocked by a PR            → now, and "when you merge it" — a person's move.
115	//   blocked by an item that has a time → after it.
116	//   blocked by a plain issue nobody is scheduled to close → NO TIME, and the lane is
117	//                                drawn broken. That is the finding, not a gap.
118	//   ready                      → the next daily anchor, the tick it will be drained on.
119	//   parked or running          → now, where the person and the machine both are.
120	export function placeItem(item, { now, axis, byNumber, moversByNumber, depth = 0 }) {
121	  const status = statusOf(item);
122	  const body = parseWorkItemBody(item.body);
123	  if (status && status.startsWith(PARK_PREFIX)) return { at: now, why: 'parked', kind: 'park' };
124	  if (status === STATUS_RUNNING_AGENT || status === STATUS_RUNNING_EXECUTOR) {
125	    return { at: now, why: 'running', kind: 'running' };
126	  }
127	  const notBefore = ms(body.notBefore);
128	  if (notBefore !== null && Number.isFinite(notBefore)) {
129	    return { at: notBefore, why: `Not-before ${body.notBefore}`, kind: 'blocked-date' };
130	  }
131	  // An unreadable `Not-before` is FLAGGED, never guessed: a relative date a person
132	  // meant is a date the machine will treat as absent, and that is worth saying.
133	  if (body.notBefore) return { at: null, why: `a relative date the parser does not read: ${body.notBefore}`, kind: 'unreadable-date', flagged: true };
134	
135	  for (const target of body.blockedBy) {
136	    const mover = moversByNumber.get(target);
137	    if (mover?.kind === 'pr') return { at: now, why: `#${target} lands when you merge PR #${mover.number}`, kind: 'blocked-pr' };
138	    const blocker = byNumber.get(target);
139	    if (!blocker) continue;
140	    if (!isQueueItem(blocker)) {
141	      // A plain issue no task and no PR will close. Nothing on the board moves it, so
142	      // the downstream item has no time at all and its lane is drawn broken.
143	      return { at: null, why: `no one is scheduled to close #${target}`, kind: 'broken', broken: true, blocker: target };
144	    }
145	    if (depth >= 4) break;                              // a cycle, or a chain past reading
146	    const upstream = placeItem(blocker, { now, axis, byNumber, moversByNumber, depth: depth + 1 });
147	    if (upstream.at === null) return { ...upstream, why: `after #${target}: ${upstream.why}` };
148	    return { at: upstream.at, why: `after #${target}`, kind: 'blocked-item' };
149	  }
150	
151	  if (status === STATUS_READY) {
152	    return { at: nextDailyAnchor(now, axis), why: 'ready — the next scheduler tick', kind: 'ready' };
153	  }
154	  // An item on no queue mark at all: nothing will pick it up, and saying so is the
155	  // whole reason it is on the board.
156	  return { at: null, why: 'unmarked — no queue status, nothing will pick this up', kind: 'unmarked', flagged: true };
157	}
