170	  }
171	  if (item && !merge) return { waits: true, why: 'its item carries no Merge policy' };
172	  if (!item) return { waits: true, why: 'no work item names this PR — nothing will land it' };
173	  // The run's own converge verdict lives in a comment this listing does not fetch, so
174	  // a PR whose item DOES authorize a merge is "still open" rather than "waits for you".
175	  return { waits: false, why: `its item authorizes ${merge}`, notRead: 'the run\'s own AUTOMERGE verdict is in a comment this page has not fetched' };
176	}
177	
178	// --- the Scheduled group's task × day grid ---------------------------------------------
179	
180	const OUTCOME_CELL = { done: 'ran', delivered: 'ran', obsolete: 'declined' };
181	
182	// One row per scheduled task, one cell per day. A cell's state is form plus the
183	// semantic set, never colour alone.
184	//
185	// A FAILURE PARK LANDS ON ITS OWN TASK'S ROW, followed by whatever the task did after
186	// it — so a hatched cell followed by filled ones is the record disagreeing with the
187	// roster's claim that the lane is held, read left to right on one line. There is no
188	// separate held-lanes row, because the contradiction is a row fact.
189	export function scheduleGrid(rows, items, axis, { now, schedule }) {
190	  const scheduled = rows.filter((r) => r.frequency && r.frequency !== 'manual');
191	  const daily = scheduled.filter((r) => r.frequency === 'daily');
192	  const others = scheduled.filter((r) => r.frequency !== 'daily');
193	
194	  const cellsFor = (row) => axis.days.map((day) => {
195	    const occurrences = items.filter((i) => {
196	      const parsed = parseWorkItemTitle(i.title);
197	      const key = parsed ? `${parsed.pack}/${parsed.task}` : null;
198	      if (key !== row.key) return false;
199	      const when = i.state === 'closed' ? ms(i.closed_at) : ms(i.updated_at);
200	      return when !== null && when >= day.start && when < day.end;
201	    });
202	
203	    if (day.future) {
204	      const at = nextAnchorFor(row, now, schedule);
205	      if (at === null || at < day.start || at >= day.end) return { day: day.day, state: 'none', count: 0 };
206	      // Predicted and WILL DECLINE are told apart by height, never by dash pattern,
207	      // which at three pixels is invisible.
208	      const willDecline = row.lastClosed?.outcome === 'obsolete';
209	      return { day: day.day, state: willDecline ? 'will-decline' : 'predicted', count: 0 };
210	    }
211	
212	    const open = occurrences.filter((i) => i.state === 'open');
213	    const park = open.find((i) => statusOf(i) === STATUS_NEEDS_HUMAN_FAILURE);
214	    if (park) return { day: day.day, state: 'failure-park', count: 1, number: park.number };
215	    const approval = open.find((i) => statusOf(i) === STATUS_NEEDS_HUMAN_APPROVAL);
216	    if (approval) return { day: day.day, state: 'parked', count: 1, number: approval.number };
217	    const running = open.find((i) => [STATUS_RUNNING_AGENT, STATUS_RUNNING_EXECUTOR].includes(statusOf(i)));
218	    if (running) return { day: day.day, state: 'running', count: 1, number: running.number };
219	
220	    const closed = occurrences.filter((i) => i.state === 'closed');
221	    if (!closed.length) return { day: day.day, state: 'none', count: 0 };
222	    const states = closed.map((i) => OUTCOME_CELL[outcomeOf(i)] ?? 'declined');
223	    return {
224	      day: day.day,
225	      state: states.includes('ran') ? 'ran' : 'declined',
226	      count: closed.length,
227	      numbers: closed.map((i) => i.number),
228	    };
229	  });
230	
231	  const gridRows = daily.map((row) => ({ key: row.key, task: row.task, pack: row.pack, cells: cellsFor(row), row }));
232	  // Everything on a longer cadence is one row: the reader's question of a weekly task
233	  // is whether it fired at all this week, not which weekday it prefers.
234	  if (others.length) {
235	    gridRows.push({
236	      key: 'other-cadences',
237	      task: `${others.length} on a longer cadence`,
238	      pack: null,
239	      collapsed: others.map((r) => r.key),
240	      cells: axis.days.map((day) => {
241	        const merged = others.map((row) => cellsFor(row).find((c) => c.day === day.day));
242	        const live = merged.filter((c) => c && c.state !== 'none');
243	        if (!live.length) return { day: day.day, state: 'none', count: 0 };
244	        const worst = ['failure-park', 'parked', 'running', 'ran', 'declined', 'predicted', 'will-decline']
245	          .find((s) => live.some((c) => c.state === s));
246	        return { day: day.day, state: worst, count: live.reduce((n, c) => n + (c.count || 1), 0) };
247	      }),
248	    });
249	  }
250	  return gridRows;
251	}
252	
253	const nextAnchorFor = (row, now, schedule) => {
254	  if (row.nextAsk?.at) return ms(row.nextAsk.at);
255	  if (!row.frequency || row.frequency === 'manual' || !schedule) return null;
256	  const at = nextAnchor(row.frequency, schedule, now);
257	  return at ? ms(at) : null;
258	};
259	
260	// --- tomorrow's human workload -----------------------------------------------------------
261	
262	// The Now group's header sentence, DERIVED and never a tile: the PRs waiting now, plus
263	// the scheduled runs whose own declaration cannot land the PR they will open. It is the
264	// `automerge` field read against the schedule, not a guess about tomorrow.
265	export function workloadLine(waitingPrs, rows, { schedule, now }) {
266	  const producers = rows.filter((r) => r.frequency && r.frequency !== 'manual'
267	    && (r.declaration?.automerge === 'nothing' || r.declaration?.automerge == null));
268	  const daily = producers.filter((r) => r.frequency === 'daily');
269	  const rest = producers.filter((r) => r.frequency !== 'daily');
270	  const parts = [`${waitingPrs} open PR${waitingPrs === 1 ? '' : 's'}`];
271	  parts.push(waitingPrs ? 'every one waits for a person' : 'nothing waits for a person');
272	  if (daily.length) parts.push(`+${daily.length} a day from ${daily.map((r) => r.task).slice(0, 2).join(', ')}${daily.length > 2 ? ` +${daily.length - 2}` : ''}`);
273	  if (rest.length) parts.push(`${rest.length} more on longer cadences`);
274	  return parts.join(' · ');
275	}
276	
277	// --- the quiet tail -------------------------------------------------------------------
278	
279	// One ruled line, not a group: the plain issues on no edge, counted by what matters.
280	export function quietTail(issues, edges, now) {
281	  const onEdge = new Set(edges.flatMap((e) => [e.from, e.to]));
282	  const quiet = issues.filter((i) => !isQueueItem(i) && !onEdge.has(i.number));
283	  const has = (i, label) => labelNames(i).includes(label);
284	  const rotting = quiet.filter((i) => (now - (ms(i.updated_at) ?? now)) >= ROT_DAYS * DAY);
285	  return {
286	    total: quiet.length,
287	    rotting: rotting.length,
288	    quickWin: quiet.filter((i) => has(i, 'quick-win')).length,
289	    needsDecision: quiet.filter((i) => has(i, 'needs-decision')).length,
290	    items: quiet.map((i) => ({
291	      number: i.number, title: i.title,
292	      idleDays: Math.floor((now - (ms(i.updated_at) ?? now)) / DAY),
293	      quickWin: has(i, 'quick-win'),
294	      needsDecision: has(i, 'needs-decision'),
295	    })).sort((a, b) => b.idleDays - a.idleDays),
296	  };
297	}
298	
299	// --- the whole board --------------------------------------------------------------------
300	
301	export function buildBoard({ rows = [], items = [], prs = [], now, schedule = null } = {}) {
302	  const axis = axisOf(now, schedule);
303	  const open = items.filter((i) => i.state === 'open');
304	  const byNumber = new Map(items.map((i) => [i.number, i]));
305	  const moversByNumber = new Map(prs.filter((p) => p.closesIssue).map((p) => [p.closesIssue, { kind: 'pr', number: p.number }]));
306	  const declarationFor = new Map(rows.map((r) => [r.key, { ...r.declaration, key: r.key }]));
307	  const edges = edgesOf(open, prs);
308	
309	  // NOW — every open PR, wired to what it closes.
310	  const nowRows = prs.filter((p) => !p.merged_at).map((pr) => {
311	    const item = pr.closesIssue ? byNumber.get(pr.closesIssue) : null;
312	    const parsed = item ? parseWorkItemTitle(item.title) : null;
313	    const declaration = parsed ? declarationFor.get(`${parsed.pack}/${parsed.task}`) : null;
314	    const flag = prWaits(pr, { item, declaration });
315	    return {
316	      id: `pr:${pr.number}`,
317	      kind: 'pr',
318	      gutter: `#${pr.number}${pr.closesIssue ? ` → #${pr.closesIssue}` : ''}`,
319	      title: pr.title,
320	      openedAt: ms(pr.created_at),
321	      waits: flag.waits,
322	      why: flag.why,
323	      notRead: flag.notRead ?? null,
324	      marks: [{ kind: 'bar', from: ms(pr.created_at), to: now, flag: flag.waits }],
325	    };
326	  }).sort((a, b) => (b.waits ? 1 : 0) - (a.waits ? 1 : 0) || a.openedAt - b.openedAt);
327	
328	  // FLOWS — ad-hoc items and the plain issues that block them, at their predicted time.
329	  const adHoc = open.filter((i) => isQueueItem(i) && labelNames(i).includes(ORIGIN_AD_HOC));
330	  const parkedOrRunning = open.filter((i) => isQueueItem(i) && !labelNames(i).includes(ORIGIN_AD_HOC)
331	    && (statusOf(i)?.startsWith(PARK_PREFIX) || [STATUS_RUNNING_AGENT, STATUS_RUNNING_EXECUTOR].includes(statusOf(i))));
332	  const flowItems = [...adHoc, ...parkedOrRunning];
333	  const flowRows = flowItems.map((item) => {
334	    const place = placeItem(item, { now, axis, byNumber, moversByNumber });
335	    const status = statusOf(item);
336	    const parkKind = status?.startsWith(PARK_PREFIX) ? status.slice(PARK_PREFIX.length) : null;
337	    return {
338	      id: `item:${item.number}`,
339	      kind: 'item',
340	      gutter: `#${item.number}`,
341	      title: item.title,
342	      at: place.at,
343	      why: place.why,
344	      place: place.kind,
345	      broken: Boolean(place.broken),
346	      blocker: place.blocker ?? null,
347	      flagged: Boolean(place.flagged),
348	      parkKind: parkKind && PARK_KINDS.includes(parkKind) ? parkKind : (parkKind ? 'failure' : null),
349	      marks: [markFor(place, parkKind, now)],
350	      finding: place.broken || place.flagged ? place.why : null,
351	    };
352	  }).sort((a, b) => (b.broken ? 1 : 0) - (a.broken ? 1 : 0)
353	    || (a.at ?? Infinity) - (b.at ?? Infinity)
354	    || a.gutter.localeCompare(b.gutter));
355	
356	  const grid = scheduleGrid(rows, items, axis, { now, schedule });
357	  const quiet = quietTail(items.filter((i) => i.state === 'open'), edges, now);
358	  const waiting = nowRows.filter((r) => r.waits).length;
359	
360	  const capped = (list) => ({ shown: list.slice(0, GROUP_CAP), more: Math.max(0, list.length - GROUP_CAP), all: list });
361	
362	  return {
363	    axis,
364	    groups: [
365	      { id: 'now', title: 'Now', count: nowRows.length, sentence: workloadLine(waiting, rows, { schedule, now }), ...capped(nowRows) },
366	      {
367	        id: 'flows', title: 'Flows', count: flowRows.length,
368	        sentence: flowRows.length
369	          ? `blocked, parked, waiting — placed at their predicted run time${flowRows.some((r) => r.broken) ? ' · a broken lane has none' : ''}`
370	          : 'nothing is blocked, parked or waiting',
371	        ...capped(flowRows),
372	      },
373	      {
374	        id: 'scheduled', title: 'Scheduled', count: grid.length,
375	        sentence: `the daily anchor is ${String(axis.dailyHour).padStart(2, '0')}:00 UTC`,
376	        shown: grid, more: 0, all: grid, grid: true,
377	      },
378	    ],
379	    quiet,
380	    edges,
381	  };
382	}
383	
384	// One mark, from a placement. Form before colour: a park's kind is its glyph, a
385	// running item is filled, a queued one is hollow, and an item on no mark is dashed.
386	function markFor(place, parkKind, now) {
387	  if (place.kind === 'park') return { kind: 'park', at: now, park: parkKind?.replace(`${PARK_PREFIX}`, '') ?? 'failure' };
388	  if (place.kind === 'running') return { kind: 'running', at: now };
389	  if (place.at === null) return { kind: 'unmarked', at: null };
390	  return { kind: 'queued', at: place.at, broken: Boolean(place.broken) };
391	}
