182	// --- work items ----------------------------------------------------------------
183	
184	// An item is a filed `[claudinite-work]` issue OR an adopted marked issue — the
185	// one-issue request model's other shape, which keeps the person's own title
186	// (tasks-dispatch DESIGN §16.1). One definition, shared with the queue's own reader.
187	export { isQueueItem as isWorkItem } from '../claudinite-tasks/shared-code/work-items.mjs';
188	
189	// THE PAGE'S FIVE STATE KEYS. Four are the engine's own status labels; the fifth is
190	// this page's own word, because a park is four labels and the page groups them into
191	// one column, routing by kind separately (`triageOf`). It is a display key and never
192	// a label: nothing writes `parked` to an issue.
193	const STATE_KEY = new Map([
194	  [STATUS_BLOCKED, BLOCKED], [STATUS_READY, READY],
195	  [STATUS_RUNNING_EXECUTOR, EXECUTING], [STATUS_RUNNING_AGENT, AGENT],
196	]);
197	
198	// The one state an open item is in, decoded from whatever spelling filed it, or
199	// `unlabelled` for an item wearing none — which is not a display quirk but the
200	// torn-label-swap leavings the janitor repairs, so it gets its own rendered state
201	// rather than being folded into "blocked".
202	export const PARKED = 'parked';
203	
204	export function stateOf(item) {
205	  if (item?.state === 'closed') return 'closed';
206	  if (isParked(item)) return PARKED;
207	  const worn = statusesOn(item).filter((s) => STATE_KEY.has(s));
208	  if (worn.length === 1) return STATE_KEY.get(worn[0]);
209	  if (worn.length > 1) return 'torn';
210	  return 'unlabelled';
211	}
212	
213	// What the park is asking for, or null for an item that is not parked. A park whose
214	// kind cannot be decoded — an older engine's bare one, a word a newer engine
215	// invented — reads as `failure`, the lane that says "someone diagnose this".
216	export const triageOf = (item) => (isParked(item) ? triageLabelFor(parkKindOf(item)) : null);
