1	// One table, three questions. Pure: no clock of its own, no I/O, no DOM.
2	//
3	// The repo page used to carry two tables — every declared task in one, every open work
4	// item in the other — and they were the same rows twice. A task's row could not say
5	// what its item was doing without repeating the item table, and an item's row could not
6	// say what it was FOR without repeating the roster. Worse, the reader had to join them
7	// by eye to answer the only question they open this page with: is anything stuck.
8	//
9	// So there is one row per piece of work, and the view decides which rows and which
10	// columns:
11	//
12	//   STUCK   — something has stopped. A park, a blown leash, an item off the state
13	//             machine, a task whose lane is held. This is the list to act on.
14	//   PENDING — work in flight or queued: an item exists and is moving.
15	//   ALL     — every declared task, including the ones that have never run, which is
16	//             the case a list built from items alone would silently omit.
17	//
18	// The classification is one function so the three views cannot disagree about what
19	// "stuck" means, and the ordering is severity-first so the top of any view is the worst
20	// thing true of this repo.
21	
22	import {
23	  BLOCKED, READY, EXECUTING, AGENT, NEEDS_HUMAN_APPROVAL, NEEDS_HUMAN_ACTION,
24	} from '../claudinite-tasks/shared-code/work-items.mjs';
25	// `PARKED` is the page's own state key, not a label — a park is four labels and the
26	// page groups them into one (model.mjs).
27	import { PARKED } from './model.mjs';
28	
29	export const VIEWS = Object.freeze(['stuck', 'pending', 'all']);
30	
31	// The severity ladder, worst first — the same words and the same order the fleet page
32	// ranks members by, so a reader moving between the two pages is reading one scale.
33	const LEVELS = ['critical', 'serious', 'warning', 'info', 'ok'];
34	const levelRank = (l) => {
35	  const i = LEVELS.indexOf(l);
36	  return i === -1 ? LEVELS.length : i;
37	};
38	
39	// The machine states an item can be in and still be moving. Anything else an OPEN item
40	// wears — a park, a torn label swap, no label at all — is a stop.
41	const MOVING = new Set([BLOCKED, READY, EXECUTING, AGENT]);
42	
43	// What is wrong with this row, worst first, or an empty list. Every entry mirrors
44	// something the engine will actually act on (or has stopped acting on), never a display
45	// heuristic — the warnings come from `describeItem`, which reads the real recovery
46	// rules, and the two added here are the two the item cannot state about itself.
47	export function troubles(row) {
48	  const out = [];
49	  const item = row.current;
50	  if (item) {
51	    if (item.state === PARKED) {
52	      out.push({
53	        level: item.blockingPark ? 'critical' : (item.triage === NEEDS_HUMAN_APPROVAL ? 'warning' : 'serious'),
54	        text: item.warnings.find((w) => w.text.startsWith('parked'))?.text ?? 'parked for a human',
55	      });
56	    }
57	    for (const w of item.warnings) {
58	      if (w.text.startsWith('parked')) continue;      // already said, at its own severity
59	      out.push(w);
60	    }
61	    if (!MOVING.has(item.state) && item.state !== PARKED) {
62	      out.push({ level: 'warning', text: 'off the state machine — the janitor repairs it' });
63	    }
64	  }
65	  // A held lane is a fact about the TASK, not about the item holding it: nothing new
66	  // will be filed for this task until the park clears, and the item's own row says
67	  // only that it is parked.
68	  if (row.nextAsk?.kind === 'held') {
69	    out.push({ level: 'critical', text: 'the task\'s lane is held — nothing new is scheduled until this clears' });
70	  }
71	  return out.sort((a, b) => levelRank(a.level) - levelRank(b.level));
72	}
73	
74	// Which view a row belongs to. `stuck` and `pending` are exclusive: an item that has
75	// stopped is not also in flight, whatever label it wears.
76	export function classify(row) {
77	  if (troubles(row).length) return 'stuck';
78	  return row.current ? 'pending' : 'idle';
79	}
80	
81	// What acts soonest, for ordering within a severity band. Acting now beats every date;
82	// a held or unreadable schedule sinks, because it has no next.
83	export function askOrder(row) {
84	  const ask = row.nextAsk ?? { kind: 'note' };
85	  if (ask.kind === 'ready' || ask.kind === 'running' || ask.kind === 'ready-soon') return 0;
86	  if (ask.at) return ask.at.getTime();
87	  return Infinity;
88	}
89	
90	// Every piece of work as one row: the declared tasks, plus any open item whose task
91	// this repo no longer declares — which is exactly the item nobody will ever pick up,
92	// and precisely what a roster-only table cannot show.
93	//
94	// `rows` is `buildRoster`'s output; `open` is the described open items.
95	export function workRows(rows, open) {
96	  const declared = new Set(rows.map((r) => r.key));
97	  const orphans = open
98	    .filter((i) => !i.key || !declared.has(i.key))
99	    .map((i) => ({
100	      key: i.key ?? `#${i.number}`,
101	      pack: i.pack,
102	      task: i.task,
103	      declaration: null,
104	      frequency: null,
105	      // Not a schedule problem to be waited out: the item names a task this repo does
106	      // not declare, so nothing will ever pick it up until a person acts.
107	      nextAsk: { kind: 'note', note: 'no declared task — nothing will pick this up' },
108	      anchorNote: null,
109	      current: i,
110	      openCount: 1,
111	      lastClosed: null,
112	      history: [],
113	      undeclared: true,
114	    }));
115	
116	  return [...rows.map((r) => ({ ...r, undeclared: false })), ...orphans].map((r) => {
117	    const t = troubles(r);
118	    return {
119	      ...r,
120	      troubles: t,
121	      // An undeclared item is a stop of its own kind, and it has no warning of its own
122	      // to carry it — the queue's recovery rules are about items whose task exists.
123	      level: r.undeclared ? 'serious' : (t.length ? t[0].level : 'ok'),
124	      view: r.undeclared ? 'stuck' : classify(r),
125	    };
126	  }).sort((a, b) => levelRank(a.level) - levelRank(b.level) || askOrder(a) - askOrder(b) || a.key.localeCompare(b.key));
127	}
128	
129	// The rows one view shows. `all` is every row; the other two are their own kind.
130	export const rowsFor = (all, view) => (view === 'all' ? all : all.filter((r) => r.view === view));
131	
132	// How many rows each view holds, so the switcher can say what it is offering instead of
133	// making the reader click to find out — and so a view with nothing in it can say
134	// "nothing is stuck" rather than rendering an empty table.
135	export function viewCounts(all) {
136	  return {
137	    stuck: all.filter((r) => r.view === 'stuck').length,
138	    pending: all.filter((r) => r.view === 'pending').length,
139	    all: all.length,
140	  };
141	}
142	
143	// The view to open on: whatever is worst and non-empty. A page whose default view is
144	// empty on a healthy repo teaches its reader that the page is broken.
145	export const defaultView = (counts) => (counts.stuck ? 'stuck' : counts.pending ? 'pending' : 'all');
146	
147	// --- what is waiting on a person ----------------------------------------------------
148	
149	// The park split, in the vocabulary the fleet page's estimate already speaks. Kept here
150	// rather than recomputed in the view so the repo page's minutes and the fleet row's
151	// minutes are the same arithmetic over the same definitions.
152	export function attentionOf(open) {
153	  const parked = open.filter((i) => i.state === PARKED);
154	  return {
155	    broken: parked.filter((i) => i.blockingPark).length,
156	    approvals: parked.filter((i) => !i.blockingPark && i.triage === NEEDS_HUMAN_APPROVAL).length,
157	    actions: parked.filter((i) => !i.blockingPark && i.triage === NEEDS_HUMAN_ACTION).length,
158	    decisions: parked.filter((i) => !i.blockingPark
159	      && ![NEEDS_HUMAN_APPROVAL, NEEDS_HUMAN_ACTION].includes(i.triage)).length,
160	    tripping: open.filter((i) => i.state !== PARKED && i.warnings.length).length,
161	  };
162	}
