306	// --- the forced wake (DESIGN §8) ----------------------------------------------
307	
308	// Which standing items a `wake` dispatch names. Forcing a scheduled task IS waking
309	// its standing item, and this is that same lever reached from OUTSIDE the repo: the
310	// fleet enforcer dispatches this workflow with the task ids it wants run now, and
311	// the member wakes its own items with its own token. The enforcer therefore needs
312	// no issue access anywhere — the fan-out model the enforcer's sweeps are built on, where
313	// the enforcer dispatches and the member executes.
314	//
315	// An id is `pack/task` or a bare `task` resolved against this repo's own discovered
316	// tasks, so a caller spanning many members never has to know any one member's pack
317	// layout. Every id that matches nothing comes back in `unmatched`: a force whose
318	// report counts only what it woke reads as coverage it did not have.
319	//
320	// An item already in flight (`task:ready`, `task:executing`, `task:agent`) is left
321	// alone and reported as `already`, never re-woken — an episode boundary dropped on
322	// a live claim is exactly the livelock F18 describes.
323	//
324	// WHEN THE STANDING ITEM DOES NOT EXIST, forcing MINTS it (§8's other lever). A
325	// task that completes closes its item, and the next one appears only when the
326	// task next says yes — so between the two there is nothing to wake, and that gap
327	// is the common case rather than an edge: a daily task is missing its item for
328	// most of the day. A force that reported "nothing to wake" there would fail on
329	// most members most of the time, which is precisely what a fleet-wide converge
330	// lever must not do. The minted item is an ordinary standing item — same title,
331	// no qualifier — stamped `Woken:` so the task's cadence terms hold on it (a
332	// person's wake stands in for the cadence) while everything else it requires
333	// still applies; it is the task's live item, so the scheduler asks nothing beside it.
334	//
335	// A WOKEN-GATED task is the exception, and never minted: it has no standing item
336	// to stand in for — an item exists only because an issue named the task (a
337	// verification's `Task:` line, a marked request), and a bare one carries nothing
338	// its worker can read, so it can only park (#1721). Its items keep their own
339	// titles, so the force reaches them by the task path in the machine block: every
340	// open one not in flight is woken, and none at all is reported, never papered
341	// over with a mint.
342	export function planWake(spec, tasks = [], items = []) {
343	  const ids = String(spec ?? '').split(/[\s,]+/).map((s) => s.trim()).filter(Boolean);
344	  const wake = []; const create = []; const already = []; const unmatched = [];
345	  for (const id of ids) {
346	    const [a, b] = id.includes('/') ? id.split('/') : [null, id];
347	    const owners = tasks.filter((t) => t.id === b && (a === null || t.pack === a));
348	    if (owners.length !== 1) {
349	      unmatched.push({ id, why: owners.length ? `${owners.length} declared packs own a "${b}" task — name it as pack/task` : 'no declared pack owns a task by that name' });
350	      continue;
351	    }
352	    const owner = owners[0];
353	    const { pack, id: task } = owner;
354	    if (!isScheduledTask(owner.decl)) {
355	      const routed = items.filter((i) => {
356	        if (i.state !== 'open') return false;
357	        const byPath = taskIdFromPath(parseWorkItemBody(i.body).taskPath);
358	        return !!byPath && byPath.pack === pack && byPath.task === task;
359	      });
360	      if (!routed.length) {
361	        unmatched.push({ id, why: `"${pack}/${task}" runs only when woken and has no open item — nothing stands for it to mint, so an item exists only where an issue names the task` });
362	        continue;
363	      }
364	      for (const item of routed) {
365	        if (IN_FLIGHT.includes(statusOf(item))) already.push({ id, issue: item.number });
366	        else wake.push({ id: `${pack}/${task}`, issue: item.number });
367	      }
368	      continue;
369	    }
370	    const item = items.find((i) => {
371	      if (i.state !== 'open') return false;
372	      const parsed = parseWorkItemTitle(i.title);
373	      return parsed && parsed.pack === pack && parsed.task === task;
374	    });
375	    if (!item) { create.push({ id: `${pack}/${task}`, pack, task, taskPath: owner.taskPath }); continue; }
376	    if (IN_FLIGHT.includes(statusOf(item))) { already.push({ id, issue: item.number }); continue; }
377	    wake.push({ id: `${pack}/${task}`, issue: item.number });
378	  }
379	  return { wake, create, already, unmatched };
380	}
