382	// The Context a forced standing item carries. It says the force is the only reason
383	// the item exists, because the executor still evaluates the precondition at pick:
384	// a force that finds no work must roll with its reason on record, not invent work.
385	export const FORCED_WAKE_CONTEXT =
386	  'Minted by a force — this task had no open standing item at the time. The wake stands in for the task\'s cadence; every other condition is still evaluated at pick, so converge to a no-op if there is nothing to do.';
387	
388	// The statuses that mean someone already holds this item — decoded, so an item any
389	// engine version filed answers the same. `running-agent` counts: the work is with a
390	// session, and waking would hand a second executor the same item.
391	const IN_FLIGHT = [STATUS_READY, STATUS_RUNNING_EXECUTOR, STATUS_RUNNING_AGENT];
392	
393	// --- CLI: the thin I/O shell the vendored scheduler run workflow invokes ---------------
394	// Reads the work-item list, plans, applies. All GitHub access is the Action's
395	// GITHUB_TOKEN. Dormancy is the first gate, before any read — a project that has
396	// said it is out of the recurring work should not pay for the list that proves it.
397	
398	// Every WORK ITEM, state=all, via the ISSUES list API — never the search index
399	// (S6/F11: search is eventually consistent, and a family list that misses a
400	// just-created item mints a duplicate standing item). Bounded by the scheduled
401	// families' need for closed history: closed items are only interesting back to the
402	// widest period, so the listing stops once it is past that.
403	//
404	// MEMBERSHIP IS `isQueueItem`, the shared predicate, and not the title prefix
405	// (#1497). An adopted marked issue IS an item under the one-issue model (DESIGN
406	// §16.1) and keeps the person's own title forever, so a prefix test drops exactly
407	// that class — and job 2 is the ONLY site that releases a blocked item, so an
408	// ad-hoc item born blocked on a `Not-before:` sat sleeping past its instant with
409	// nothing left to wake it (#1267, #1349, #1351, #1396). The executor and the
410	// janitor already read the queue through this predicate; this list was the one that
411	// did not.
412	export async function listWorkItems(gh, repo, { since = null } = {}) {
413	  const out = [];
414	  for (let page = 1; ; page += 1) {
415	    const q = `state=all&sort=created&direction=desc&per_page=100&page=${page}`
416	      + (since ? `&since=${encodeURIComponent(since)}` : '');
417	    const { status, json } = await gh(`/repos/${repo}/issues?${q}`);
418	    // A page that could not be read is not the end of the list. Breaking on it
419	    // truncates the queue mid-pagination and the run plans against the remainder:
420	    // a standing item whose page never arrived reads as absent, and the run mints a
421	    // second one beside it.
422	    if (status !== 200 || !Array.isArray(json)) {
423	      throw new Error(`could not list work items in ${repo} at page ${page} (${status}) — a truncated queue is not a shorter one`);
424	    }
425	    if (json.length === 0) break;
426	    for (const i of json) {
427	      if (i.pull_request) continue;
428	      if (!isQueueItem(i)) continue;
429	      out.push({
430	        number: i.number, title: i.title, body: i.body ?? '', state: i.state,
431	        labels: labelNames(i), created_at: i.created_at, closed_at: i.closed_at,
432	        updated_at: i.updated_at,
433	      });
434	    }
435	    if (json.length < 100) break;
436	  }
437	  return out;
438	}
