507	// Which `Blocked-by` targets this run still has to read. A target need not be a
508	// work item — a fan-in blocks on whatever its children are — so states come from
509	// the fetched items first and a direct read otherwise, and `known` is what has
510	// already been answered.
511	//
512	// A marked issue's blockers count the same way: adoption decides whether the item
513	// it births is born blocked or ready, and an unread state is never `closed`, so a
514	// missing read delays the request rather than releasing it (§16.11).
515	//
516	// Extracted from `main` so it can be called at all. Nothing else here drives
517	// `main`, whose body is I/O against a live Action, so an identifier it names and
518	// never imports resolves at run time or not at all — and the request half went
519	// three days without executing once, behind an adoption list that was always
520	// empty (#1354).
521	export function blockersToResolve(items, requests, known) {
522	  const wanted = new Set();
523	  for (const i of items) {
524	    if (i.state !== 'open' || !isStatus(i, STATUS_BLOCKED)) continue;
525	    for (const n of parseWorkItemBody(i.body).blockedBy) if (!known.has(n)) wanted.add(n);
526	  }
527	  for (const r of requests) {
528	    for (const n of parseBlockedBy(r.body)) if (!known.has(n)) wanted.add(n);
529	  }
530	  return wanted;
531	}
