533	async function main() {
534	  // THE OPERATOR HOLD, FIRST ACT (§15.24) — before the config load, before the
535	  // first API call, so a held queue reads nothing and writes nothing rather than
536	  // deriving the world and then declining to act on it.
537	  if (isSuspended()) { console.log('## Claudinite scheduler run\n'); console.log(suspendedNotice()); return; }
538	  const { makeGh, actionRepoContext } = await import('../signals/gh.mjs');
539	  const { discoverTasks } = await import('../discover.mjs');
540	  const { loadConfig, isDormant } = await import('../../../engine/checks/helpers/repo-context.mjs');
541	  const { ensureLabels, addLabel, removeLabel, comment, closeIssue, createIssue, listComments } = await import('../github.mjs');
542	
543	  const root = process.cwd();
544	  const { repo, defaultBranch } = actionRepoContext();
545	  if (!repo) { console.error('GITHUB_REPOSITORY not set — not in an Actions context'); process.exit(1); }
546	  const config = loadConfig(root);
547	
548	  console.log('## Claudinite scheduler run\n');
549	  if (isDormant(config)) {
550	    console.log('- this project declares itself dormant — no items instantiated, readied or reclaimed');
551	    return;
552	  }
553	
554	  const gh = makeGh();
555	  const { tasks, errors } = await discoverTasks(root, config);
556	  for (const e of errors) console.log(`! ${e.what}`);
557	
558	  const now = new Date();
559	  // Closed items matter only back to the run-history horizon — the longest any
560	  // cadence term looks; older history can never change a verdict.
561	  const since = new Date(now.getTime() - RUN_HORIZON_DAYS * 86400e3).toISOString();
562	  const items = await listWorkItems(gh, repo, { since });
563	  const requests = await listMarkedIssues(gh, repo);
564	
565	  const known = new Map(items.map((i) => [i.number, i.state]));
566	  for (const n of blockersToResolve(items, requests, known)) {
567	    const { status, json } = await gh(`/repos/${repo}/issues/${n}`);
568	    known.set(n, status === 200 ? json?.state ?? null : null);
569	  }
570	
571	  // One comment read per EXECUTING item — never per item in the repo — so the
572	  // reclaim can measure the holder's own silence rather than the issue's.
573	  for (const item of items) {
574	    if (item.state !== 'open' || !isStatus(item, STATUS_RUNNING_EXECUTOR)) continue;
575	    item.livenessAt = lastLivenessAt(await listComments(gh, repo, item.number));
576	  }
