578	  // THE ASK (DESIGN §5), in two passes. The task's run-history terms — its
579	  // cadence, its view of its last failure — read only the queue this run already
580	  // holds, so they are judged FIRST, and a task they decline costs no other read at
581	  // all: a weekly task asked twice a day collects nothing on the thirteen ticks it
582	  // says no. Only where they cannot decide alone are the task's other signals
583	  // collected and the whole expression judged. Any read the scheduler cannot make
584	  // is an `error`, which fails OPEN in the plan. The scheduler stub holds no
585	  // FLEET_GITHUB_TOKEN (unlike the executor workflow), so a fleet task fails open
586	  // here on exactly the ticks its cadence holds and the executor decides.
587	  const { collectSignalsForTask, windowDaysOf } = await import('./signals.mjs');
588	  const collectFor = collectSignalsForTask({ gh, repo, root, config, defaultBranch, items });
589	  const evaluate = async (task) => {
590	    if (task.decl.preconditions === undefined) return { error: 'the task declares no "preconditions"' };
591	    const packConfig = config.packConfig?.[task.pack] ?? {};
592	    const judge = (signals, partial) => evaluatePreconditions({
593	      preconditions: task.decl.preconditions,
594	      signals,
595	      config: packConfig,
596	      terms: task.terms,
597	      windowDays: windowDaysOf(task, signals),
598	      schedule: config.taskScheduler,
599	      // The instant this ask is for, so a clock-reading term answers about the
600	      // occurrence being planned rather than about the moment the run happens to
601	      // reach it.
602	      now,
603	      partial,
604	    });
605	
606	    let history;
607	    try { history = await collectFor(task, now, null, { only: ['runs'] }); }
608	    catch (e) { return { error: `signal collection failed: ${e.message}` }; }
609	    const first = judge(history, true);
610	    if (first.error || first.run === false || first.run === true) return first;
611	
612	    const names = taskSignalNames(task.decl, task.terms);
613	    if (names.includes('fleet')) {
614	      const { makeFleetGh } = await import('../signals/fleet.mjs');
615	      if (!makeFleetGh()) return { error: 'the `fleet` signal needs FLEET_GITHUB_TOKEN, which the scheduler run does not hold' };
616	    }
