59	// Parse a declaration into `{ kind: 'conditions', conditions }` (each condition an
60	// array of alternatives) or `{ kind: 'invalid', reason }`. Names are not resolved
61	// here — that needs the task's own terms, which the static check and the
62	// evaluator each supply.
63	export function parsePreconditions(preconditions) {
64	  const invalid = (reason) => ({ kind: 'invalid', reason });
65	  if (!Array.isArray(preconditions) || preconditions.length === 0) {
66	    return invalid('it is not a non-empty array of condition strings');
67	  }
68	  if (!preconditions.every((e) => typeof e === 'string' && e.trim() !== '')) {
69	    return invalid('every entry must be a non-empty string');
70	  }
71	  const conditions = preconditions.map((entry) => String(entry).split(ALTERNATIVE).map(parseTerm));
72	  if (conditions.some((alts) => alts.some((t) => t.name === ''))) {
73	    return invalid(`an alternative around "${ALTERNATIVE}" is empty`);
74	  }
75	  if (conditions.flat().some((t) => t.name === NONE)) {
76	    return invalid(`"${NONE}" is retired — a task with no condition would run at every scheduler tick. State when it runs: a cadence (\`${DUE_TERM}:daily\`, \`${ELAPSED_TERM}:7d\`), \`${WOKEN_TERM}\` for a task that runs only when somebody asks, or the movement it waits for`);
