95	// Every signal the expression's terms read. The collector union cannot disagree
96	// with what the gate actually consults, because it IS what the gate consults —
97	// which a separately declared list could not guarantee.
98	export function preconditionSignals(preconditions, taskTerms) {
99	  const parsed = parsePreconditions(preconditions);
100	  if (parsed.kind !== 'conditions') return [];
