110	// Everything about a declaration that is decidable without signals: the grammar,
111	// the term names, their arguments, and a task-local term shadowing a built-in.
112	// Returns `{ what, fix }` problems — empty means well-formed.
113	export function validatePreconditions(preconditions, taskTerms = new Map()) {
114	  const problems = [];
115	  const bad = (what, fix) => problems.push({ what, fix });
116	  for (const name of taskTerms.keys?.() ?? []) {
117	    if (BUILTIN_TERMS.has(name)) {
118	      bad(`the task's preconditions.mjs redefines the built-in term "${name}"`,
