463	// --- the verdict --------------------------------------------------------------
464	
465	// Evaluate a declaration over collected signals. Returns `{ run, reason, context }`
466	// — or `{ error }`, which is a failed run rather than a decline.
467	//
468	// `schedule` is the repo's `taskScheduler` anchor settings, which `due:` reads.
469	//
470	// PARTIAL MODE (`partial: true`) judges what the bundle so far can decide: a term
471	// whose signal has not been collected is UNKNOWN rather than false, a conjunct
472	// with an unknown alternative and no held one stays open, and the verdict is `{
473	// run: null, undecided: true, missing }` unless some conjunct is already decided
474	// false — a decline that cost nothing beyond the run history — or every conjunct
475	// held. The scheduler asks this way first, with the `runs` bundle alone, so a
476	// task whose cadence declines never collects its other signals. In full mode a
477	// missing signal is a term that does not hold, as it always was.
478	export function evaluatePreconditions({
479	  preconditions, signals = {}, config = {}, item = null, terms = new Map(), windowDays = null, now = null,
480	  schedule = null, partial = false,
481	}) {
482	  const parsed = parsePreconditions(preconditions);
483	  if (parsed.kind === 'invalid') return { error: `the "preconditions" declaration is not legal: ${parsed.reason}` };
484	
485	  const held = [];
486	  const context = [];
487	  const missing = new Set();
488	  let declined = null;
489	  let undecided = false;
490	  for (const alternatives of parsed.conditions) {
491	    const outcomes = [];
492	    let unknown = false;
493	    for (const ref of alternatives) {
494	      const term = resolveTerm(ref.name, terms);
495	      if (!term) return { error: `unknown precondition "${ref.name}" — no built-in and none this task's preconditions.mjs exports` };
496	      const argProblem = argumentProblem(term, ref);
497	      if (argProblem) return { error: argProblem.what };
498	      // An unreadable signal is never a verdict: the term would be ruling on data
499	      // that was not there, and a decline taken that way is permanent silence.
500	      const unreadable = (term.signals ?? []).find((n) => signals?.[n]?.error);
501	      if (unreadable) return { error: `${ref.name}: the \`${unreadable}\` signal could not be read — ${signals[unreadable].error}` };
502	      if (partial) {
503	        const absent = (term.signals ?? []).filter((n) => signals?.[n] === undefined);
504	        if (absent.length) { absent.forEach((n) => missing.add(n)); unknown = true; continue; }
505	      }
506	      let out;
507	      try { out = term.holds(signals, { arg: ref.arg, config, item, windowDays, now, schedule }) ?? {}; }
508	      catch (e) { return { error: `the precondition "${ref.name}" threw: ${e.message}` }; }
509	      if (out.error) return { error: `${ref.name}: ${out.error}` };
510	      outcomes.push({ ref, out });
511	    }
512	    const winner = outcomes.find((o) => o.out.holds === true);
513	    if (winner) {
514	      held.push(winner.out.reason ?? winner.ref.text);
515	      context.push(...(winner.out.context ?? []));
516	    } else if (unknown) {
517	      undecided = true;
518	    } else if (declined === null) {
519	      declined = outcomes.map((o) => o.out.reason ?? `${o.ref.text} does not hold`).join('; nor ');
520	    }
521	  }
522	  if (declined !== null) return { run: false, reason: declined };
523	  if (undecided) return { run: null, undecided: true, missing: [...missing] };
524	  return { run: true, reason: held.join('; '), context };
525	}
