1	// Signal collection for ONE task (tasks-dispatch DESIGN §5, §6.4): exactly that
2	// task's declared union, collected at the moment a verdict is asked for. Two
3	// callers ask — the scheduler run at every tick (a read it cannot make fails open
4	// there) and the executor at pick, which re-derives rather than trusting the
5	// tick's answer forward.
6	//
7	// THE RUN HISTORY COMES FIRST, always: the `runs` bundle is what the cadence
8	// terms read, and it is also what sets the WINDOW every other collector reads
9	// over — since this task's newest run started, so a task reads exactly what moved
10	// since it last looked, and one that declined for a week then sees the week. With
11	// no run in the horizon the window is the task's own cadence (a day for a task
12	// stating none) plus an hour of slack. Overlap at the seam — a run's own duration
13	// — is absorbed by the preconditions' own dedupe, as the old fixed lookback's was.
14	
15	import { periodMs } from './anchors.mjs';
16	import { itemFacts } from './work-item.mjs';
17	import { taskSignalNames, taskCadence } from '../task-contract.mjs';
18	
19	const DAY_MS = 86400e3;
20	const SLACK_MS = 3600e3;
21	
22	// The window a task reads with no run of its own to measure from: its cadence
23	// term's period, a day where it states none.
24	export function defaultWindowMs(task) {
25	  const cadence = taskCadence(task?.decl);
26	  if (cadence?.kind === 'due') return periodMs(cadence.cadence) + SLACK_MS;
27	  if (cadence?.kind === 'elapsed') return cadence.ms + SLACK_MS;
28	  return DAY_MS + SLACK_MS;
29	}
30	
31	// The window, from the run history: `{ sinceIso, days }`. The newest run that
32	// actually ran — a `rejected` item declined at pick and did nothing, so it does not
33	// move the seam — anchors it at its start; none in the horizon falls back to the
34	// task's default.
35	export function windowFromRuns(task, runs, now) {
36	  const nowMs = new Date(now).getTime();
37	  const last = (runs?.list ?? []).find((r) => r.outcome !== 'obsolete');
38	  const sinceMs = last && Number.isFinite(new Date(last.createdAt).getTime())
39	    ? new Date(last.createdAt).getTime()
40	    : nowMs - defaultWindowMs(task);
41	  return { sinceIso: new Date(sinceMs).toISOString(), days: (nowMs - sinceMs) / DAY_MS };
42	}
43	
44	// The lookback in DAYS a verdict is judged over — what a term needs when its
45	// dimension carries an age rather than a windowed flag of its own (the
46	// conversation-logs branch reports how old its newest capture is, not whether one
47	// landed). Read off the collected bundle, which is where the window was decided.
48	export const windowDaysOf = (task, signals) => signals?.runs?.window?.days ?? defaultWindowMs(task) / DAY_MS;
49	
50	// A collector factory bound to this run's repo context; the returned function is
51	// the `collectSignalsFor` seam the scheduler run and the executor call.
52	//
53	// `items` is the queue where the caller already fetched it (the scheduler run),
54	// so the run history of every task costs no read. `only` narrows a collection to
55	// the named signals — the scheduler's cheap first pass asks for `['runs']` alone
56	// and judges the run-history terms before anything else is collected.
57	export function collectSignalsForTask({ gh, repo, root, config, defaultBranch, items = null }) {
58	  return async function collectFor(task, now, item = null, { only = null } = {}) {
59	    const { collectSignals } = await import('../signals/index.mjs');
60	    const { buildSignalContext } = await import('../signals/context.mjs');
61	    const names = taskSignalNames(task.decl, task.terms);
62	    const packConfigFor = (packId) => config.packConfig?.[packId] ?? {};
63	    const nowIso = new Date(now).toISOString();
64	    const facts = itemFacts(item);
65	    const taskRef = { pack: task.pack, id: task.id };
66	
67	    // The history first, on its own: it needs no window and decides the window.
68	    const history = buildSignalContext({ root, repo, defaultBranch, now: nowIso, sinceIso: null, config, packConfigFor, item: facts, task: taskRef, items });
69	    const { runs } = await collectSignals(gh, history, ['runs']);
70	    const window = windowFromRuns(task, runs?.error ? null : runs, now);
71	    const out = { runs: { ...runs, window } };
72	
73	    const rest = (only ? names.filter((n) => only.includes(n)) : names).filter((n) => n !== 'runs');
74	    if (!rest.length) return out;
75	
76	    // The fleet aggregate is a full enumeration over a wider credential, so it is
77	    // built only when THIS task declares it and only where that credential exists.
78	    // Absent, the collector returns null and a fleet task's precondition declines
79	    // rather than crashing.
80	    let fleet = null;
81	    if (rest.includes('fleet')) {
82	      const { readFleet, makeFleetGh } = await import('../signals/fleet.mjs');
83	      const fleetGh = makeFleetGh();
84	      if (fleetGh) {
85	        fleet = await readFleet(fleetGh, { owner: repo.split('/')[0], canonRepo: repo, sinceIso: window.sinceIso });
86	        if (fleet.error) console.log(`! fleet enumeration: ${fleet.error}`);
87	      } else {
88	        console.log('- this task declares the `fleet` signal but FLEET_GITHUB_TOKEN is not set');
89	      }
90	    }
91	
92	    const ctx = buildSignalContext({
93	      root, repo, defaultBranch, now: nowIso, sinceIso: window.sinceIso, config, fleet, packConfigFor,
94	      // The occurrence's own facts, for the collector that reads one named object
95	      // rather than a window (the request read, DESIGN §16.4).
96	      item: facts, task: taskRef, items,
97	    });
98	    return { ...out, ...(await collectSignals(gh, ctx, rest)) };
99	  };
100	}
