46	// THE ONE DOOR (DESIGN §17.1). Applied by `normalizeTaskDeclaration`, so every reader downstream
47	// of a loaded declaration sees a canonical token — and there is more downstream than the
48	// calendar: `periodMs` feeds the janitor's stale-ready bound (`queue/janitor-rules.mjs`) and the
49	// precondition's signal window (`queue/signals.mjs`). Normalizing only the anchor would leave a
50	// task that now runs daily judged stale after two HOURS, which is a spurious needs-human park on
51	// exactly the members this tolerance exists for.
52	export const normalizeFrequency = (frequency) => LEGACY_FREQUENCIES[frequency] ?? frequency;
