54	// The documented anchor defaults (per-project-scheduling DESIGN §2) — applied
55	// when a repo omits `schedule` or any of its keys. This is the single source of
56	// these values; the checks layer's load-time range validation
57	// (engine/checks/helpers/repo-context.mjs) only bounds them, it does not
58	// re-declare them.
59	export const DEFAULT_SCHEDULE = { dailyHour: 4, weeklyDay: 'Sun', monthlyDay: 1 };
60	
61	// Sun-indexed to match Date#getUTCDay (0 = Sunday). Also the canonical weekday
62	// vocabulary the config validator mirrors.
63	export const WEEKDAYS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
64	
65	const HOUR_MS = 3600 * 1000;
66	const DAY_MS = 24 * HOUR_MS;
67	
68	// Last calendar day of a UTC month (day 0 of the next month rolls back).
69	const daysInMonth = (year, monthIndex) => new Date(Date.UTC(year, monthIndex + 1, 0)).getUTCDate();
70	
71	// Fill any absent key with its documented default; leave present values
72	// untouched (the checks layer has already range-validated them at load).
73	export function normalizeSchedule(schedule = {}) {
74	  const s = schedule || {};
75	  return {
76	    dailyHour: Number.isInteger(s.dailyHour) ? s.dailyHour : DEFAULT_SCHEDULE.dailyHour,
77	    weeklyDay: WEEKDAYS.includes(s.weeklyDay) ? s.weeklyDay : DEFAULT_SCHEDULE.weeklyDay,
78	    monthlyDay: Number.isInteger(s.monthlyDay) ? s.monthlyDay : DEFAULT_SCHEDULE.monthlyDay,
79	  };
80	}
81	
82	// The most recent occurrence of `frequency` at or before `now`, as a Date —
83	// `null` for `manual`, which has none. `now` may be a Date or anything the Date
84	// constructor accepts; `schedule` is normalized here, so callers need not.
85	export function anchorInstant(frequency, schedule, now) {
86	  const s = normalizeSchedule(schedule);
87	  const at = new Date(now);
88	  const nowMs = at.getTime();
89	  // Total over the accepted vocabulary, not just the canonical one: the door normalizes every
90	  // LOADED declaration, and normalizing here too means a direct caller — a test, `slots.mjs`, a
91	  // frequency read off something other than a discovered task — cannot get a different answer.
92	  const freq = normalizeFrequency(frequency);
93	
94	  if (freq === 'manual') return null;
95	
96	  if (freq === 'daily') {
97	    // Walk anchor DATES back from today until the instant is ≤ now: today's anchor hour may not
98	    // have come yet, in which case the most recent occurrence is yesterday's.
99	    let anchor = new Date(Date.UTC(at.getUTCFullYear(), at.getUTCMonth(), at.getUTCDate()));
100	    for (;;) {
101	      const time = new Date(anchor.getTime() + s.dailyHour * HOUR_MS);
102	      if (time.getTime() <= nowMs) return time;
103	      anchor = new Date(anchor.getTime() - DAY_MS);
104	    }
105	  }
106	
107	  if (freq === 'weekly') {
108	    const targetDow = WEEKDAYS.indexOf(s.weeklyDay);
109	    let date = new Date(Date.UTC(at.getUTCFullYear(), at.getUTCMonth(), at.getUTCDate()));
110	    // Up to 8 steps guarantees the previous week's occurrence even when today is
111	    // the weekly day but earlier than dailyHour.
112	    for (let i = 0; i < 8; i += 1) {
113	      if (date.getUTCDay() === targetDow) {
114	        const time = new Date(date.getTime() + s.dailyHour * HOUR_MS);
115	        if (time.getTime() <= nowMs) return time;
116	      }
117	      date = new Date(date.getTime() - DAY_MS);
118	    }
119	    // Unreachable in practice (a matching weekday always exists within 7 days).
120	    throw new Error(`no weekly occurrence resolved for ${s.weeklyDay}`);
121	  }
122	
123	  if (freq === 'monthly') {
124	    let year = at.getUTCFullYear();
125	    let month = at.getUTCMonth();
126	    for (;;) {
127	      const day = Math.min(s.monthlyDay, daysInMonth(year, month)); // clamp to month length (DESIGN §2)
128	      const time = new Date(Date.UTC(year, month, day) + s.dailyHour * HOUR_MS);
129	      if (time.getTime() <= nowMs) return time;
130	      month -= 1;
131	      if (month < 0) { month = 11; year -= 1; }
132	    }
133	  }
134	
135	  throw new Error(`unknown frequency "${frequency}"`);
136	}
