138	// --- the cadence terms ----------------------------------------------------------
139	// How a task states WHEN it runs, inside its own `preconditions` (tasks-dispatch
140	// DESIGN §5): the engine keeps no calendar of its own, so the cadence is one of the
141	// task's conditions, read off its own run history at every scheduler tick.
142	//
143	//   due:<daily|weekly|monthly>   no run since that cadence's most recent anchor on
144	//                                this repo's schedule — fixed hours, no drift
145	//   last-run-over:<12h|1d|7d>    the newest run started more than that long ago
146	//   woken                        only from an item somebody created — the spelling
147	//                                of the retired `frequency: manual`
148	//
149	// The parse lives here, beside the frequency vocabulary it replaces, and imports
150	// nothing: the dashboard's browser bundle reads a cadence the way the scheduler does.
151	export const CADENCES = ['daily', 'weekly', 'monthly'];
152	export const DUE_TERM = 'due';
153	export const ELAPSED_TERM = 'last-run-over';
154	export const NOT_FAILED_TERM = 'last-run-not-failed';
155	export const WOKEN_TERM = 'woken';
156	
157	// `12h`, `1d`, `7d` — a whole number of hours or days, nothing else.
158	const DURATION_RE = /^(\d+)(h|d)$/;
159	export function parseDuration(text) {
160	  const m = DURATION_RE.exec(String(text ?? ''));
161	  if (!m) return null;
162	  const n = Number(m[1]);
163	  return n > 0 ? n * (m[2] === 'h' ? HOUR_MS : DAY_MS) : null;
164	}
165	
166	// The term references an expression carries: each entry split on `||`, each
167	// reference `{ name, arg }` with the argument after the first colon. The same
168	// grammar precondition-policy.mjs parses, re-spelled here so this module stays
169	// import-free; the policy engine's parse is the one that validates.
170	const alternativesOf = (entry) => String(entry ?? '').split('||').map((t) => t.trim()).filter(Boolean)
171	  .map((t) => { const c = t.indexOf(':'); return c === -1 ? { name: t, arg: null } : { name: t.slice(0, c).trim(), arg: t.slice(c + 1).trim() }; });
172	const entriesOf = (preconditions) => (Array.isArray(preconditions) ? preconditions : []).map(alternativesOf);
173	
174	// The cadence a declaration states — `{ kind: 'due', cadence }`, `{ kind:
175	// 'elapsed', ms, text }`, `{ kind: 'woken' }`, or null for a task with no cadence
176	// term at all (asked at every tick, it runs whenever its other conditions hold).
177	// The first cadence term wins; `woken` only counts where it gates.
178	export function cadenceOf(preconditions) {
179	  for (const ref of entriesOf(preconditions).flat()) {
180	    if (ref.name === DUE_TERM && CADENCES.includes(ref.arg)) return { kind: 'due', cadence: ref.arg };
181	    if (ref.name === ELAPSED_TERM) {
182	      const ms = parseDuration(ref.arg);
183	      if (ms) return { kind: 'elapsed', ms, text: ref.arg };
184	    }
185	  }
186	  return isWokenGated(preconditions) ? { kind: 'woken' } : null;
187	}
188	
189	// A task runs only when somebody asks when `woken` is a whole conjunct of its
190	// expression — `['woken', …]` gates, `['due:daily || woken']` merely widens.
191	export const isWokenGated = (preconditions) =>
192	  entriesOf(preconditions).some((alts) => alts.length === 1 && alts[0].name === WOKEN_TERM && alts[0].arg === null);
193	
194	// What the retired `frequency` field always meant, as the term that now says it.
195	export const cadenceTermFor = (frequency) =>
196	  (normalizeFrequency(frequency) === 'manual' ? WOKEN_TERM : `${DUE_TERM}:${normalizeFrequency(frequency)}`);
