382	// The Context a forced standing item carries. It says the force is the only reason
383	// the item exists, because the executor still evaluates the precondition at pick:
384	// a force that finds no work must roll with its reason on record, not invent work.
385	export const FORCED_WAKE_CONTEXT =
386	  'Minted by a force — this task had no open standing item at the time. The wake stands in for the task\'s cadence; every other condition is still evaluated at pick, so converge to a no-op if there is nothing to do.';
387	
388	// The statuses that mean someone already holds this item — decoded, so an item any
389	// engine version filed answers the same. `running-agent` counts: the work is with a
390	// session, and waking would hand a second executor the same item.
391	const IN_FLIGHT = [STATUS_READY, STATUS_RUNNING_EXECUTOR, STATUS_RUNNING_AGENT];
