34	// The retired empty precondition. The contract's door still strips it from a
35	// declaration that carries a `frequency` (the cadence term takes its place); on
36	// its own it is an error, named below.
37	export const NONE = 'none';
38	
39	const ALTERNATIVE = '||';
40	
41	// How many paths or numbers a term's context names before it says how many it
42	// dropped. A window can carry more files than one session should read, and a
43	// silently truncated list reads as the whole window.
44	export const MAX_CONTEXT_ITEMS = 40;
