46	// --- the grammar --------------------------------------------------------------
47	
48	// One term reference: its name, and the inline argument after its first colon
49	// (`commits-under:.claudinite/local`). The rest of the string is the argument
50	// verbatim, so a path argument may itself contain colons.
51	function parseTerm(text) {
52	  const raw = String(text ?? '').trim();
53	  const colon = raw.indexOf(':');
54	  return colon === -1
55	    ? { name: raw, arg: null, text: raw }
56	    : { name: raw.slice(0, colon).trim(), arg: raw.slice(colon + 1).trim(), text: raw };
57	}
