150	    return { what: `the precondition "${ref.name}" takes no argument but was given "${ref.arg}"`, fix: `write it as "${ref.name}"` };
151	  }
152	  if (term.takesArg && term.argOk && !term.argOk(ref.arg)) {
153	    return { what: `"${ref.name}" takes ${term.argHint}, not "${ref.arg}"`, fix: `write it as "${ref.name}:<${term.argName ?? 'value'}>" — ${term.argHint}` };
154	  }
155	  return null;
156	}
157	
158	// --- the built-in vocabulary --------------------------------------------------
159	// A term is `{ signals, takesArg?, argName?, holds(signals, opts) }`, where
160	// `holds` returns `{ holds, reason?, context? }` or `{ error }`. `opts` carries
161	// the inline `arg`, the pack's `config`, this occurrence's `item` fields,
162	// `windowDays` — the lookback the signals were collected over, which the
163	// dimensions with no windowed field of their own (the logs branch) need — and
164	// `now`, the instant this verdict is being taken at.
165	//
166	// `now` is passed rather than read, because a term whose subject IS the instant
167	// ("are we inside the festival month") has nothing in the signal bundle to read:
168	// a term reaching for the process clock would be untestable at a chosen moment
169	// and impure, in the one module that promises to be neither. Both callers already
170	// hold the instant they are deciding for, so passing it costs nothing and keeps
171	// every term a pure function of its inputs.
172	//
173	// EVERY MOVEMENT TERM IS NON-TASK BY CONSTRUCTION: the fields they read are
174	// already classified by the collectors, which drop a commit or a PR carrying the
175	// `Claudinite-Task:` trailer. That is the whole silence gate — a movement-gated
176	// task cannot be woken by another task's output, and no operator or marker says
177	// so in the declaration.
178	
179	const commitsOf = (s) => s?.commits ?? {};
180	const touchedPaths = (s) => commitsOf(s).touchedPaths ?? [];
181	
182	// THE RUN HISTORY: this task's own unqualified work items, newest first, other
183	// than the item under evaluation — what the `runs` collector reads off the issue
184	// list over a fixed horizon. Each `{ number, createdAt, closedAt, state, status,
185	// park, outcome }`. The engine keeps no other memory of a task: the queue IS the
186	// record, which is why a renamed task simply reads as never having run.
187	const runsOf = (s) => s?.runs?.list ?? [];
188	const newestRun = (s) => runsOf(s)[0] ?? null;
189	const ms = (t) => (t == null ? null : new Date(t).getTime());
190	const ago = (fromMs, nowMs) => {
191	  const h = Math.round((nowMs - fromMs) / 3600e3);
192	  return h < 48 ? `${h}h` : `${Math.round(h / 24)}d`;
193	};
194	
195	// A person's wake stands in for the cadence: the cadence terms hold on a woken
196	// item, and everything else the task requires still applies, so a force that
197	// finds no work still says so.
198	const wokenReason = (item) => (item?.woken === true
199	  ? { holds: true, reason: `#${item.number ?? '?'} was woken by hand — the wake stands in for the cadence` }
200	  : null);
201	const substantiveShas = (s) => (commitsOf(s).list ?? []).filter((c) => c.substantive).map((c) => c.sha.slice(0, 7));
202	
203	// A capped list plus what it dropped — the shape every scope-naming context uses.
204	const cappedContext = (items, lead, dropTail) => {
205	  const scope = items.slice(0, MAX_CONTEXT_ITEMS);
206	  const dropped = items.length - scope.length;
207	  return [
208	    `${lead}: ${scope.join(', ')}.`,
209	    ...(dropped ? [`${dropped} further ${dropTail}`] : []),
210	  ];
211	};
212	
213	// The scheduler's own work items wear a `task:*` label for their whole life. The
214	// issues collector hides them by title, so one filed under any other title still
215	// reaches here; the label is the invariant, and it filters BOTH ways — such an
216	// issue is neither a touch that triggers a run nor a target inside one.
217	const nonTaskIssues = (s) => {
218	  const open = (s?.issues?.open ?? []).filter((i) => !(i.labels ?? []).some((l) => String(l).startsWith('task:')));
219	  const inScope = new Set(open.map((i) => i.number));
220	  return { open, touched: (s?.issues?.touched ?? []).filter((n) => inScope.has(n)) };
221	};
222	
223	const capturedInWindow = (s, windowDays) => {
224	  const age = s?.conversationLogs?.newestLogAgeDays;
225	  if (typeof windowDays !== 'number') return { error: 'the lookback window is unknown, so "a session captured in the window" cannot be decided' };
226	  // null/undefined is UNKNOWN — no branch, or no readable stamp — which is not movement.
227	  return { holds: typeof age === 'number' && age <= windowDays };
228	};
229	
230	const openPrs = (s) => s?.prs?.open ?? [];
231	
232	const BUILTIN_TERMS = new Map(Object.entries({
233	  // --- the run-history terms (tasks-dispatch DESIGN §5) ----------------------
234	  // Judged before any other signal is collected — the `runs` bundle comes off the
235	  // issue list the scheduler already holds — so a task whose cadence declines
236	  // costs no read at all on the ticks it does not run.
237	
238	  // No run since the cadence's most recent anchor on this repo's schedule. Both
239	  // halves of the old occurrence guard: an item CREATED since the anchor is this
240	  // period's, and so is one CLOSED since it — an item that started before the
241	  // anchor and ran past it consumed this period, and a second one is a double run.
242	  [DUE_TERM]: {
243	    signals: ['runs'],
244	    takesArg: true,
245	    argName: 'daily|weekly|monthly',
246	    argOk: (arg) => CADENCES.includes(arg),
247	    argHint: `one of ${CADENCES.join(', ')}`,
248	    holds(s, { arg, item, now, schedule }) {
249	      const woken = wokenReason(item);
250	      if (woken) return woken;
251	      // The instant is the caller's to supply (a term never reads the clock); the
252	      // schedule falls back to the documented defaults the way every anchor read does.
253	      if (ms(now) === null || Number.isNaN(ms(now))) return { error: `${DUE_TERM}:${arg} has no instant to anchor on — the caller supplied no \`now\`` };
254	      const anchor = anchorInstant(arg, schedule ?? {}, now);
255	      const anchorMs = anchor.getTime();
256	      const since = runsOf(s).find((r) => (ms(r.createdAt) ?? -Infinity) >= anchorMs || (ms(r.closedAt) ?? -Infinity) >= anchorMs);
257	      return since
258	        ? { holds: false, reason: `#${since.number} already ran since the ${arg} anchor at ${anchor.toISOString()}` }
259	        : { holds: true, reason: `no run since the ${arg} anchor at ${anchor.toISOString()}` };
260	    },
261	  },
262	
263	  // The newest run STARTED more than the duration ago — an item's creation is when
264	  // the task was last asked and said yes. No run in the horizon holds: the task
265	  // has not run in longer than any duration this term can state.
266	  [ELAPSED_TERM]: {
267	    signals: ['runs'],
268	    takesArg: true,
269	    argName: '12h|1d|7d',
270	    argOk: (arg) => parseDuration(arg) !== null,
271	    argHint: 'a whole number of hours or days, e.g. 12h, 1d, 7d',
