281	        ? { holds: true, reason: `the newest run, #${newest.number}, started ${ago(startedMs, nowMs)} ago — over ${arg}` }
282	        : { holds: false, reason: `the newest run, #${newest.number}, started ${ago(startedMs, nowMs)} ago, inside ${arg}` };
283	    },
284	  },
285	
286	  // Whether a failed run stops the next one is the task's to say, and only by
287	  // stating this: absent, the next occurrence is filed beside the park. Only the
288	  // newest run speaks — a failure behind a later clean run is history.
289	  [NOT_FAILED_TERM]: {
290	    signals: ['runs'],
291	    holds(s) {
292	      const newest = newestRun(s);
293	      if (!newest) return { holds: true, reason: 'no run of this task to have failed' };
294	      return newest.park === 'failure'
295	        ? { holds: false, reason: `the newest run, #${newest.number}, stands at a failure park — this task declares it does not run past its own failure` }
296	        : { holds: true, reason: `the newest run, #${newest.number}, did not fail` };
297	    },
298	  },
299	
300	  // Only from an item somebody created — a mark, a hand-created item, a wake, a
301	  // forced mint. The scheduler's own ask has no item, so it never holds there,
302	  // which is what keeps such a task off the schedule without any field saying so.
303	  [WOKEN_TERM]: {
304	    signals: [],
305	    holds(_s, { item }) {
306	      return item?.woken === true
307	        ? { holds: true, reason: `#${item.number ?? '?'} was created or woken by hand` }
308	        : { holds: false, reason: 'the scheduler\'s own ask — this task runs only from an item somebody created' };
309	    },
310	  },
311	
312	  // --- the movement terms -----------------------------------------------------
313	  // The positive umbrella over all four activity dimensions — what a
314	  // cadence-triggered task states when its value is zero on a repo nobody works
315	  // in. The first active window resumes it.
316	  'repo-active': {
317	    signals: ['commits', 'issues', 'prs', 'conversationLogs'],
318	    holds(s, { windowDays }) {
319	      const captured = capturedInWindow(s, windowDays);
320	      if (captured.error) return captured;
321	      const moved = [];
322	      if (commitsOf(s).substantiveChange === true) moved.push('a substantive commit landed');
323	      if (nonTaskIssues(s).touched.length) moved.push(`${nonTaskIssues(s).touched.length} issue(s) moved`);
324	      if ((s?.prs?.touched ?? []).length) moved.push(`${(s.prs.touched ?? []).length} open PR(s) moved`);
325	      if (captured.holds) moved.push('a session was captured');
326	      return moved.length
327	        ? { holds: true, reason: `the repo was active in the window — ${moved.join(', ')}` }
328	        : { holds: false, reason: 'the repo was silent in the window — no substantive commit, no issue or PR of its own moved, and no session was captured' };
329	    },
330	  },
331	
332	  'substantive-change': {
333	    signals: ['commits'],
334	    holds(s) {
335	      // The collector's own verdict is the condition — it is where a commit is
336	      // classified, trailer and all. The sha list is only what the context names,
337	      // and a collector that could not detail the commits still answers the gate.
338	      if (commitsOf(s).substantiveChange !== true) {
339	        return { holds: false, reason: 'no substantive default-branch change in the window' };
340	      }
341	      const shas = substantiveShas(s);
342	      return {
343	        holds: true,
344	        reason: `${shas.length || 'a'} substantive default-branch commit(s) in the window`,
345	        context: shas.length ? cappedContext(shas, 'Substantive commits in the window', 'commit(s) are not named here.') : [],
346	      };
347	    },
348	  },
349	
350	  // Task-authored movement included, deliberately: for the tasks that measure the
351	  // machinery itself rather than the project.
352	  'any-commit': {
353	    signals: ['commits'],
354	    holds(s) {
355	      const count = commitsOf(s).count ?? 0;
356	      return count > 0
357	        ? { holds: true, reason: `${count} default-branch commit(s) in the window` }
358	        : { holds: false, reason: 'no default-branch commit in the window' };
359	    },
360	  },
361	
362	  'session-captured': {
363	    signals: ['conversationLogs'],
364	    holds(s, { windowDays }) {
365	      const captured = capturedInWindow(s, windowDays);
366	      if (captured.error) return captured;
367	      return captured.holds
368	        ? { holds: true, reason: 'a conversation log was captured in the window' }
369	        : { holds: false, reason: 'no conversation log was captured in the window' };
370	    },
371	  },
372	
373	  'issues-touched': {
374	    signals: ['issues'],
375	    holds(s) {
376	      const { touched } = nonTaskIssues(s);
377	      return touched.length
378	        ? { holds: true, reason: `${touched.length} issue(s) moved in the window`, context: cappedContext(touched.map((n) => `#${n}`), 'Issues touched in the window', 'touched issue(s) are not named here.') }
379	        : { holds: false, reason: 'no issue of this repo\'s own moved in the window' };
380	    },
381	  },
382	
383	  'prs-touched': {
384	    signals: ['prs'],
385	    holds(s) {
386	      const touched = s?.prs?.touched ?? [];
387	      return touched.length
388	        ? { holds: true, reason: `${touched.length} open PR(s) moved in the window`, context: cappedContext(touched.map((n) => `#${n}`), 'PRs opened or updated in the window', 'moved PR(s) are not named here.') }
389	        : { holds: false, reason: 'no open PR was opened or updated in the window' };
390	    },
391	  },
392	
393	  'mount-moved': {
394	    signals: ['sharedMount'],
395	    holds(s) {
396	      const packs = s?.sharedMount?.changedPacks ?? [];
397	      return packs.length
398	        ? { holds: true, reason: `declared pack(s) changed in the mounted canon: ${packs.join(', ')}`, context: [`Canon packs that changed in the window: ${packs.join(', ')}.`] }
399	        : { holds: false, reason: 'no declared pack\'s vendored files changed in the window' };
400	    },
401	  },
402	
403	  'commits-under': {
404	    signals: ['commits'],
405	    takesArg: true,
406	    argName: 'path-prefix',
407	    holds(s, { arg }) {
408	      const under = touchedPaths(s).filter((p) => p.startsWith(arg));
409	      return under.length
410	        ? { holds: true, reason: `${under.length} path(s) under ${arg} changed in the window`, context: cappedContext(under, `Paths under ${arg} that changed in the window`, `path(s) under ${arg} are not named here.`) }
411	        : { holds: false, reason: `no path under ${arg} changed in the window` };
412	    },
413	  },
414	
415	  'commits-outside': {
416	    signals: ['commits'],
417	    takesArg: true,
418	    argName: 'path-prefix',
419	    holds(s, { arg }) {
420	      const outside = touchedPaths(s).filter((p) => !p.startsWith(arg));
421	      return outside.length
422	        ? {
423	          holds: true,
424	          reason: `${outside.length} path(s) outside ${arg} changed in the window`,
425	          context: cappedContext(outside, `Paths outside ${arg} that changed in the window — work exactly these, and no others`,
426	            `path(s) changed in the window and are NOT in scope this round — say so in the wrap-up, so it is not read as a full sweep.`),
427	        }
428	        : { holds: false, reason: `nothing outside ${arg} changed in the window` };
429	    },
430	  },
431	
432	  // The two pending-round conditions. Both exist so an unreviewed round is never
433	  // stacked on one already in flight, which is why an open PR whose paths could
434	  // not be read counts as PENDING: unknown is not clear.
435	  'no-open-pr-touching': {
436	    signals: ['prs'],
437	    takesArg: true,
438	    argName: 'path-prefix',
439	    holds(s, { arg }) {
440	      const pending = openPrs(s).find((p) => Array.isArray(p.changedPaths) && p.changedPaths.some((f) => f.startsWith(arg)));
