export function anchorInstant(frequency, schedule, now) {
  const s = normalizeSchedule(schedule);
  const at = new Date(now);
  const nowMs = at.getTime();
  // Total over the accepted vocabulary, not just the canonical one: the door normalizes every
  // LOADED declaration, and normalizing here too means a direct caller — a test, `slots.mjs`, a
  // frequency read off something other than a discovered task — cannot get a different answer.
  const freq = normalizeFrequency(frequency);

  if (freq === 'manual') return null;

  if (freq === 'daily') {
    // Walk anchor DATES back from today until the instant is ≤ now: today's anchor hour may not
    // have come yet, in which case the most recent occurrence is yesterday's.
    let anchor = new Date(Date.UTC(at.getUTCFullYear(), at.getUTCMonth(), at.getUTCDate()));
    for (;;) {
      const time = new Date(anchor.getTime() + s.dailyHour * HOUR_MS);
      if (time.getTime() <= nowMs) return time;
      anchor = new Date(anchor.getTime() - DAY_MS);
    }
  }

  if (freq === 'weekly') {
    const targetDow = WEEKDAYS.indexOf(s.weeklyDay);
    let date = new Date(Date.UTC(at.getUTCFullYear(), at.getUTCMonth(), at.getUTCDate()));
    // Up to 8 steps guarantees the previous week's occurrence even when today is
    // the weekly day but earlier than dailyHour.
    for (let i = 0; i < 8; i += 1) {
      if (date.getUTCDay() === targetDow) {
        const time = new Date(date.getTime() + s.dailyHour * HOUR_MS);
        if (time.getTime() <= nowMs) return time;
      }
      date = new Date(date.getTime() - DAY_MS);
    }
    // Unreachable in practice (a matching weekday always exists within 7 days).
    throw new Error(`no weekly occurrence resolved for ${s.weeklyDay}`);
  }

  if (freq === 'monthly') {
    let year = at.getUTCFullYear();
    let month = at.getUTCMonth();
    for (;;) {
      const day = Math.min(s.monthlyDay, daysInMonth(year, month)); // clamp to month length (DESIGN §2)
      const time = new Date(Date.UTC(year, month, day) + s.dailyHour * HOUR_MS);
      if (time.getTime() <= nowMs) return time;
      month -= 1;
      if (month < 0) { month = 11; year -= 1; }
    }
  }

  throw new Error(`unknown frequency "${frequency}"`);
}

// --- the cadence terms ----------------------------------------------------------
// How a task states WHEN it runs, inside its own `preconditions` (tasks-dispatch
// DESIGN §5): the engine keeps no calendar of its own, so the cadence is one of the
// task's conditions, read off its own run history at every scheduler tick.
//
//   due:<daily|weekly|monthly>   no run since that cadence's most recent anchor on
//                                this repo's schedule — fixed hours, no drift
//   last-run-over:<12h|1d|7d>    the newest run started more than that long ago
//   woken                        only from an item somebody created — the spelling
//                                of the retired `frequency: manual`
//
// The parse lives here, beside the frequency vocabulary it replaces, and imports
// nothing: the dashboard's browser bundle reads a cadence the way the scheduler does.
export const CADENCES = ['daily', 'weekly', 'monthly'];
export const DUE_TERM = 'due';
export const ELAPSED_TERM = 'last-run-over';
export const NOT_FAILED_TERM = 'last-run-not-failed';
export const WOKEN_TERM = 'woken';

// `12h`, `1d`, `7d` — a whole number of hours or days, nothing else.
const DURATION_RE = /^(\d+)(h|d)$/;
export function parseDuration(text) {
  const m = DURATION_RE.exec(String(text ?? ''));
  if (!m) return null;
  const n = Number(m[1]);
  return n > 0 ? n * (m[2] === 'h' ? HOUR_MS : DAY_MS) : null;
}

// The term references an expression carries: each entry split on `||`, each
// reference `{ name, arg }` with the argument after the first colon. The same
// grammar precondition-policy.mjs parses, re-spelled here so this module stays
// import-free; the policy engine's parse is the one that validates.
const alternativesOf = (entry) => String(entry ?? '').split('||').map((t) => t.trim()).filter(Boolean)
  .map((t) => { const c = t.indexOf(':'); return c === -1 ? { name: t, arg: null } : { name: t.slice(0, c).trim(), arg: t.slice(c + 1).trim() }; });
const entriesOf = (preconditions) => (Array.isArray(preconditions) ? preconditions : []).map(alternativesOf);

// The cadence a declaration states — `{ kind: 'due', cadence }`, `{ kind:
// 'elapsed', ms, text }`, `{ kind: 'woken' }`, or null for a task with no cadence
// term at all (asked at every tick, it runs whenever its other conditions hold).
// The first cadence term wins; `woken` only counts where it gates.
export function cadenceOf(preconditions) {
  for (const ref of entriesOf(preconditions).flat()) {
    if (ref.name === DUE_TERM && CADENCES.includes(ref.arg)) return { kind: 'due', cadence: ref.arg };
    if (ref.name === ELAPSED_TERM) {
      const ms = parseDuration(ref.arg);
      if (ms) return { kind: 'elapsed', ms, text: ref.arg };
    }
  }
  return isWokenGated(preconditions) ? { kind: 'woken' } : null;
}

// A task runs only when somebody asks when `woken` is a whole conjunct of its
// expression — `['woken', …]` gates, `['due:daily || woken']` merely widens.
export const isWokenGated = (preconditions) =>
  entriesOf(preconditions).some((alts) => alts.length === 1 && alts[0].name === WOKEN_TERM && alts[0].arg === null);

// What the retired `frequency` field always meant, as the term that now says it.
export const cadenceTermFor = (frequency) =>
  (normalizeFrequency(frequency) === 'manual' ? WOKEN_TERM : `${DUE_TERM}:${normalizeFrequency(frequency)}`);

const escapesTaskDir = (cmd) => /(^|\s)\//.test(cmd) || cmd.includes('..');

// Task execution is two similar, consecutive phases — deterministic CODE-WORK,
// then AGENTIC WORK — and the field names say so. Neither phase is named for
// the other: the code phase is not preparation for the agent, it is the first
// of two peers, and a task may declare only it.
//
// Two renames have reached these fields (2026-08-06 agent_preprocessing →
// prework, 2026-08-18 prework → code-work). Every legacy key maps straight to
// today's canonical name rather than to its immediate successor, so a declaration
// written for the oldest vocabulary normalizes in one pass, and a canonical name
// wins where both are present.
//
// Scaffolding, not a second vocabulary the contract keeps: `legacy-task-fields`
// reports a declaration still on an old spelling, and the acceptance ends one
// convergence window after that advisory ships (#1642). Not "once nobody declares
// them" — nothing here can count that.
// @legacy-tolerance advisory:legacy-task-fields retire:#1642
export const LEGACY_FIELDS = {
  agent_preprocessing: 'code_work',
  agent_preprocessing_timeout: 'code_work_timeout',
  prework: 'code_work',
  prework_timeout: 'code_work_timeout',
  after: 'schedule_after',
  // 2026-09-03: the secrets a task needs are the CODE-WORK phase's (that is the
  // only phase that runs Action-side, where a secret exists), and the name says so.
  required_secrets: 'code_work_required_secrets',
};

// The defaults live in task-defaults.mjs — a module with no imports, so the
// dashboard's browser bundle can fill them the way the loader does.
export { DEFAULT_AUTOMERGE, DEFAULT_AGENT_MODEL } from './task-defaults.mjs';

// WHEN a task runs, read off its declaration (tasks-dispatch DESIGN §5): the
// cadence term it states, and whether it is on the schedule at all. A task is
// SCHEDULED unless `woken` gates it — the scheduler asks every scheduled task at
// every tick, and a woken-gated one only ever runs from an item somebody created.
export const taskCadence = (decl) => cadenceOf(decl?.preconditions);
export const isScheduledTask = (decl) => !!decl && !isWokenGated(decl.preconditions);

// Return the declaration with canonical field names and the defaults filled in.
// Non-objects pass through untouched so validateTaskDeclaration still reports
// them. Loaders (discover, resolve-dispatch) normalize once; everything
// downstream sees only `code_work` and never an absent defaulted field.
export function normalizeTaskDeclaration(decl) {
  if (decl === null || typeof decl !== 'object' || Array.isArray(decl)) return decl;
  const out = { ...decl };
  // The editor's schema pointer, when a caller hands over a parsed task.json whole.
  delete out.$schema;
  for (const [legacy, canonical] of Object.entries(LEGACY_FIELDS)) {
    if (out[legacy] !== undefined) {
      if (out[canonical] === undefined) out[canonical] = out[legacy];
      delete out[legacy];
    }
  }
  // THE FREQUENCY DOOR (tasks-dispatch DESIGN §5). `frequency` is retired: a task's
  // cadence is one of its own preconditions, read off its run history. A declaration
  // still carrying the field reads exactly as it always did — the field becomes the
  // cadence term it always meant, first in the expression, and a `none` beside it
  // (the empty precondition it used to need) drops. The field itself does not
  // survive the door: nothing downstream reads it.
  //
  // Scaffolding, not a second vocabulary: `legacy-task-fields` reports the field,
  // and the nightly update rewrites a member's own task files, so the acceptance
  // ends one convergence window after this ships (#1725).
  // @legacy-tolerance advisory:legacy-task-fields retire:#1725
  if (out.frequency !== undefined) {
    const stated = Array.isArray(out.preconditions) ? out.preconditions.filter((e) => String(e).trim() !== NONE) : [];
    if (ACCEPTED_FREQUENCIES.includes(out.frequency)) {
      const term = cadenceTermFor(out.frequency);
      out.preconditions = stated.some((e) => String(e).trim() === term) ? stated : [term, ...stated];
    } else {
      // An illegal frequency is still reported, as the illegal condition it becomes.
      out.preconditions = [`${DUE_TERM}:${out.frequency}`, ...stated];
    }
    delete out.frequency;
  }
  // The retired outcome ceilings become the outcome/policy pair. An explicit
  // `automerge` beside a legacy spelling wins: a half-migrated declaration
  // keeps the narrower intent it states.
  if (LEGACY_OUTCOMES[out.expected_outcome] !== undefined) {
    if (out.automerge === undefined) out.automerge = LEGACY_OUTCOMES[out.expected_outcome];
    out.expected_outcome = 'fresh_pr';
  }
  if (LEGACY_CEILINGS[out.expected_outcome] !== undefined) out.expected_outcome = LEGACY_CEILINGS[out.expected_outcome];
  return applyTaskDefaults(out);
}

// What a task's run does to PULL REQUESTS (tasks-dispatch DESIGN §6.4b, decision
// §15.32) — the write ceiling and the target in one word, resolved once by the
// executor before code-work and handed to both phases:
----
  // it COULD NOT ANSWER. The third is a run failure rather than a verdict (F27):
  // a decline is a decision about the world, and one taken on an API that would
  // not answer is a guess whose write-backs cannot land.
  if (decl.precondition !== undefined) {
    bad('the task declares a "precondition" function, which is retired', 'move the gate into "preconditions" — a built-in condition, or a term this task\'s preconditions.mjs exports');
  }
  // REQUIRED, with no default (DESIGN §5): the expression is the whole of when the
  // task runs, so a declaration without one has not said. A retired `frequency`
  // arrives here already turned into its cadence term by the door.
  if (decl.preconditions === undefined) {
    bad('the task declares no "preconditions"', 'add "preconditions": a list of named conditions, all of which must hold — a cadence first where the task keeps one ("due:daily", "due:weekly", "last-run-over:7d"), "woken" for a task run only from an item somebody created, then what it waits for (e.g. ["due:daily", "substantive-change"])');
  } else {
    for (const problem of validatePreconditions(decl.preconditions, terms)) bad(problem.what, problem.fix);
  }

  /**
   * model_from_request — OPTIONAL, and reserved to the engine's own built-in task.
   * A task that declares it runs at the model the ITEM names (`Model:`, written by
   * the scheduler run from a write-gated label), falling back to `agent_model` when the item
   * names none. It is the only field that lets anything on an item define behaviour,
   * so it is fenced rather than waved through (DESIGN §16.7): the shape check accepts

  QUEUED_LABEL, ORIGIN_AD_HOC, REQUEST_LABEL, workItemTitle, statusOf, parkKindOf, outcomeOf, parseWorkItemBody,
} from '../queue/work-item.mjs';
import { isQueueItem } from '../queue/read.mjs';
import { APPROVAL_RE } from '../built-in-tasks.mjs';
import { taskFromMessage } from '../task-trailer.mjs';

// How far back the run history reads (tasks-dispatch DESIGN §5): the longest any
// cadence term looks, a month, plus slack. A run older than this is not in the
// record — a task then reads as not having run in that long, which is the honest
// state-free answer. The scheduler's own queue read is bounded by the same figure.
export const RUN_HORIZON_DAYS = 40;

// A default-branch commit is genuine project work unless it is bot/CI
// housekeeping or one of Claudinite's own automated writes — the same exclusions
// the fleet planner applies (kept in sync), extended with the scheduler's own
// `[claudinite-task]` and `[claudinite-work]` writes so neither dispatch
----
        .some((l) => [ORIGIN_AD_HOC, QUEUED_LABEL, REQUEST_LABEL].includes(l)),
      author,
      authorPermission,
      approvals,
    };
  },

  // THE RUN HISTORY (tasks-dispatch DESIGN §5): this task's own unqualified work
  // items over the horizon, newest first, the item under evaluation excluded — what
  // the cadence terms and the since-last-run window read. Off `ctx.items` where the
  // caller already holds the queue (the scheduler run fetched it, so the whole
  // repo's tasks cost no read); off the ISSUES list API otherwise (the executor at
  // pick) — never the search index (S6/F11), and `since` bounded to the horizon so
  // a long-lived repo's closed history is not paged.
  //
  // A qualified item (a fan-out target, a request naming its issue) is not a run of
  // the task's standing occurrence and is not evidence of one; it is invisible here.
  async runs(gh, ctx) {
    if (!ctx.task?.pack || !ctx.task?.id) throw new Error('the runs collector needs the task whose history it reads');
    const title = workItemTitle({ pack: ctx.task.pack, task: ctx.task.id });
    const horizonIso = new Date(new Date(ctx.now).getTime() - RUN_HORIZON_DAYS * 86400e3).toISOString();
    const items = ctx.items ?? await readWorkItems(gh, ctx.repo, horizonIso);
    const list = items
      .filter((i) => String(i.title ?? '').trim() === title && i.number !== ctx.item?.number)
      .map((i) => ({
        number: i.number,
        createdAt: i.created_at,
        closedAt: i.closed_at ?? null,
        state: i.state,
        status: statusOf(i),
        park: parkKindOf(i),
        outcome: outcomeOf(i),
        woken: parseWorkItemBody(i.body ?? '').woken !== null,
      }))
      .sort((a, b) => b.number - a.number);
    return { list, horizonDays: RUN_HORIZON_DAYS };
  },

  async fleet(gh, ctx) {
    return ctx.fleet ?? null;
  },

  try {
    await main(['--root', root]);
    assert.ok(existsSync(join(root, CANON_PACK_ROOT, 'p/tasks/one/task.json')));
    assert.ok(existsSync(join(root, LOCAL_PACK_ROOT, 'q/tasks/two/task.json')));
    assert.ok(existsSync(join(root, CANON_PACK_ROOT, 'p/queue/tasks/three/task.mjs')), 'a folder outside the pack roots is not scanned');
    await main(['--root', root, `${CANON_PACK_ROOT}/p/queue/tasks/three`]);
    const three = JSON.parse(readFileSync(join(root, CANON_PACK_ROOT, 'p/queue/tasks/three/task.json'), 'utf8'));
    assert.equal(three.$schema, '../../../../claudinite-tasks/task.schema.json');
  } finally { removeTree(root); }
});

// The migration op: gated on the record's probe, inert for a caller lacking the
// capabilities, and one runner with every other op (applyMigration).
test('applyTaskDeclarationConversion: converts local packs only, gated on appliesTo and on the io', async () => {
  const root = repo({
    [`${TASK}/task.mjs`]: MODULE,
    [`${CANON_PACK_ROOT}/p/tasks/one/task.mjs`]: MODULE,
    [`.claudinite/shared/${SCHEMA_FILE}`]: '{}',
  });
  try {
    const io = { ...checkoutIo(root), move: () => {}, readTemplate: () => null };
    const record = { id: 'r', taskDeclarationsToJson: true, appliesTo: async () => true };
    assert.deepEqual(await applyTaskDeclarationConversion({ id: 'r' }, io), [], 'a record without the flag converts nothing');
    assert.deepEqual(await applyTaskDeclarationConversion({ ...record, appliesTo: async () => false }, io), [], 'the probe gates it');
    const { listDir, ...classic } = io;
    assert.deepEqual(await applyTaskDeclarationConversion(record, classic), [], 'an older caller without the listing converts nothing');
    const applied = await applyMigration(record, io);
    assert.equal(applied.length, 1);
    assert.ok(existsSync(join(root, TASK, 'task.json')));
    assert.ok(existsSync(join(root, CANON_PACK_ROOT, 'p/tasks/one/task.mjs')), 'the shared/canon packs are the canon\'s to convert');
  } finally { removeTree(root); }
});

test('task-declarations-json record: applies only where the mounted pack reads task.json, in either root', async () => {
  const m = (await loadMigrations()).find((x) => x.id === 'task-declarations-json');
  assert.ok(m, 'discovered');
  assert.equal(m.taskDeclarationsToJson, true);
  const capable = "export const TASK_DECLARATION_FILE = 'task.json';\n";
  assert.equal(await m.appliesTo(async (p) => (p.startsWith('.claudinite/shared/') ? capable : null)), true, 'a member\'s mount');
  assert.equal(await m.appliesTo(async (p) => (p.startsWith('.claudinite/shared/') ? null : capable)), true, 'the canon\'s own tree');
  assert.equal(await m.appliesTo(async () => "export const TASK_DECLARATION_FILE = 'task.mjs';\n"), false, 'an older pack');
  assert.equal(await m.appliesTo(async () => null), false, 'an unreadable mount is not capable');
  assert.equal(await m.legacyPresent(() => true, async () => 'x'), false);
  // The descriptions are the apply stage's: judgment, briefed to the session.
  assert.match(m.applyStage.why, /description/);
  assert.match(m.applyStage.instructions, /no `description`/);
  assert.match(m.applyStage.instructions, /fifty words/);
});

// The canon's own declarations, converted: each loads through the door to a
// complete declaration — pinned here so the conversion is not re-proven by hand
....
  const abs = (p) => join(root, p);
  return {
    exists: (p) => existsSync(abs(p)),
    read: (p) => (existsSync(abs(p)) ? readFileSync(abs(p), 'utf8') : null),
    write: (p, text) => { mkdirSync(dirname(abs(p)), { recursive: true }); writeFileSync(abs(p), text); },
    remove: (p) => rmSync(abs(p), { force: true }),
    listDir: (p) => { try { return readdirSync(abs(p)); } catch { return null; } },
    importModule: (p) => import(pathToFileURL(abs(p)).href),
  };
}

export async function main(argv = process.argv.slice(2)) {
  let root = process.env.CLAUDE_PROJECT_DIR || process.cwd();
  const dirs = [];
  for (let i = 0; i < argv.length; i++) {
    if (argv[i] === '--root') root = argv[++i];
    else dirs.push(argv[i]);
  }
  const io = checkoutIo(root);
  const targets = dirs.length
    ? dirs.map((d) => posix.normalize(relative(root, join(root, d)).split('\\').join('/')))
