// STANDING OR AD-HOC, DERIVED (DESIGN §15.26). A task's standing item is the one
// the scheduler files when the task says yes: its title names the task and nothing
// else, and the task it names is on the schedule. Everything else is ad-hoc — a
// woken-gated task's item (the scheduler never asks it) and every qualified item
// (a fan-out target, a request naming its issue), each of which may legitimately
// run beside the occurrence rather than being it.
//
// It is read off the item and the declaration at HEAD rather than off a label the
// creator applied, because the two could disagree: a marker says what its writer
// believed, the structure says what the item IS, and the guards that consume this
// (the live-item guard, the dedupe, the `after` yield) are only sound on the
// second. `scheduled` is whether the task the title names is asked by the
// scheduler (`isScheduledTask` in task-contract.mjs) — null when the repo no
// longer carries it, which is ad-hoc by the same rule.
export function isStandingItem(item, scheduled) {
  const parsed = parseWorkItemTitle(item?.title ?? item);
  return !!parsed && parsed.qualifier === null && scheduled === true;
}

// --- comment markers ----------------------------------------------------------
// The three comments the protocol reads back. They are HTML comments so a human
// reading the item sees prose, and they are here — with the labels and the body
// fields — because together they ARE the item's vocabulary, the one compatibility
// surface across engine versions (DESIGN §14).
//
// The CLAIM comment carries who and when (executor identity is an unbounded set
// and must never become a label). The HANDOFF comment names the session and the
// invocation nonce. The EPISODE comment is the boundary the claim arbiter is
// scoped to: every claim before it is dead, and arbitrating over dead claims makes
// one outrank every future live claimant — the item then livelocks through reclaim
// cycles forever (F18). A reclaim, a revert and a hand re-queue each write one.
export const CLAIM_MARKER = '<!-- claudinite-claim -->';
export const HANDOFF_MARKER = '<!-- claudinite-handoff -->';
export const EPISODE_MARKER = '<!-- claudinite-episode -->';

// --- the body -----------------------------------------------------------------

export const NOT_BEFORE_FIELD = 'Not-before';
export const BLOCKED_BY_FIELD = 'Blocked-by';

// `Ends-when` is a PARK'S END CONDITION (#1468) — the one field a park carries that
// says what would make it stop being a question. `#<n> closed` is its only grammar,
// and its target is whatever the park is waiting on: an approval park's pull
// request, an action park's setup issue. Nothing else is recognised, so a hand-written
// condition the janitor cannot evaluate reads as absent rather than as satisfied.
//
// It is NOT `Blocked-by`, which governs the ready/blocked lane and releases an item
// to run again; this one ENDS an item that already ran.
export const ENDS_WHEN_FIELD = 'Ends-when';
export const ENDS_WHEN_CLOSED = 'closed';

// THE TARGET (DESIGN §6.4b) — which branch and pull request this run works on,
// decided by the executor once the precondition said go and stamped here at the
// hand-off, so the agent reads it where it reads everything else and never picks a
// branch of its own. `Target-pr` is present only when the run AMENDS an open pull
// request; `Supersedes` names the task's earlier pull requests a
// `supersede_existing_pr` run closes once its own exists — read back by the
// session's converge, which performs those closes.
export const TARGET_BRANCH_FIELD = 'Target-branch';
export const TARGET_PR_FIELD = 'Target-pr';
export const SUPERSEDES_FIELD = 'Supersedes';

// WOKEN (DESIGN §5, §8) — the instant somebody created this item by hand or woke
// it: a hand-created item, a forced mint, a `--wake`. The cadence terms hold on a
// woken item (a person's wake stands in for the cadence) and the `woken` term holds
// only on one, so an item the scheduler filed on its own never carries the field.
// Stamped by the lever that woke it, never inferred from a comment.
export const WOKEN_FIELD = 'Woken';

// The three fields a REQUEST item carries (DESIGN §16.3, §16.11). `Request` is the issue this
// run implements — the whole payload, since the request task has no code-work phase
// to hand one over. `Model` is the family the asker chose, copied here by the scheduler run
// from a write-gated label and read only by a task that declares
// `model_from_request`; it is the first thing an item carries that defines
// behaviour, which is why it is fenced rather than waved through (§16.7).
export const REQUEST_FIELD = 'Request';
----
}

// THE ITEM'S OWN FACTS, as a precondition term sees them (DESIGN §16.4, §5): the
// body's fields plus the two the terms read that are not fields — the issue number,
// and whether somebody created or woke this item. `woken` is everything that is
// NOT the scheduler's own ask: an item stamped by a lever, one born ad-hoc (a
// marked issue, a chain link), and any qualified item (a fan-out target, a request
// naming its issue) — the scheduler files only unqualified planned items, so an
// item of any other shape exists because somebody asked, which is what the `woken`
// term and the cadence terms need to know.
export function itemFacts(item) {
  if (!item) return null;
  const fields = parseWorkItemBody(item.body);
  const parsed = parseWorkItemTitle(item.title);
  const schedulesOwn = !!parsed && parsed.qualifier === null && originOf(item) !== ORIGIN_AD_HOC;
  return {
    ...fields,
    number: item.number ?? null,
    woken: fields.woken !== null || !schedulesOwn,
  };
}

// WHAT A MARKED ISSUE ASKS FOR (DESIGN §16.3, §16.7, §16.11) — read from the
// person's own text at every adoption, so each ask names its parameters afresh and
// nothing stale outranks a new one.
//

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { evaluatePreconditions, parsePreconditions, validatePreconditions, preconditionSignals } from '../precondition-policy.mjs';
import { cadenceOf, isWokenGated, cadenceTermFor, parseDuration } from '../calendar.mjs';

// The run-history terms (tasks-dispatch DESIGN §5): a task's cadence, its view of
// its own last failure, and whether it runs only when somebody asks — every one a
// condition over the `runs` signal, the task's own unqualified work items newest
// first, read at every scheduler tick. Pure over that bundle, so each case here is
// the real evaluator against a hand-built history at a chosen instant.

const SCHEDULE = { dailyHour: 4, weeklyDay: 'Sun', monthlyDay: 1 };
const NOW = '2026-09-09T16:20:00Z'; // a Wednesday; today's daily anchor is 04:00Z, the weekly one Sunday the 6th
const run = (over = {}) => ({
  number: 10, createdAt: '2026-09-08T04:05:00Z', closedAt: '2026-09-08T04:40:00Z', state: 'closed',
  status: 'task:status:done', park: null, outcome: 'done', ...over,
});
const runs = (...list) => ({ runs: { list, horizonDays: 40 } });
const evaluate = (preconditions, signals, over = {}) =>
  evaluatePreconditions({ preconditions, signals, schedule: SCHEDULE, now: NOW, windowDays: 1.05, ...over });

// --- due:<cadence> ------------------------------------------------------------

test('due:daily holds only while no run of the task started or ended since today\'s anchor', () => {
  assert.equal(evaluate(['due:daily'], runs()).run, true, 'no run at all');
  assert.equal(evaluate(['due:daily'], runs(run())).run, true, 'yesterday\'s run is before today\'s 04:00 anchor');
  const today = run({ createdAt: '2026-09-09T04:05:00Z', closedAt: '2026-09-09T04:30:00Z' });
  assert.equal(evaluate(['due:daily'], runs(today)).run, false, 'a run since the anchor consumed today');
  // Both halves of the occurrence guard (F13): an item CREATED before the anchor
  // that CLOSED after it ran today, and a second one today is a double execution.
  const straddling = run({ createdAt: '2026-09-09T03:50:00Z', closedAt: '2026-09-09T04:10:00Z' });
  assert.equal(evaluate(['due:daily'], runs(straddling)).run, false);
  assert.match(evaluate(['due:daily'], runs(today)).reason, /already ran since/);
});

test('due:weekly and due:monthly anchor on the repo\'s own schedule', () => {
  const lastWeek = run({ createdAt: '2026-09-05T04:05:00Z', closedAt: '2026-09-05T05:00:00Z' });
  const thisWeek = run({ createdAt: '2026-09-07T04:05:00Z', closedAt: '2026-09-07T05:00:00Z' });
  assert.equal(evaluate(['due:weekly'], runs(lastWeek)).run, true);
  assert.equal(evaluate(['due:weekly'], runs(thisWeek)).run, false);
  assert.equal(evaluate(['due:monthly'], runs(lastWeek)).run, false, 'the 5th is after the 1st');
  const lastMonth = run({ createdAt: '2026-08-20T04:05:00Z', closedAt: '2026-08-20T05:00:00Z' });
  assert.equal(evaluate(['due:monthly'], runs(lastMonth)).run, true);
  // A member anchored elsewhere moves every cadence with it.
  const late = { ...SCHEDULE, dailyHour: 20 };
  assert.equal(evaluate(['due:daily'], runs(run({ createdAt: '2026-09-09T04:05:00Z', closedAt: '2026-09-09T05:00:00Z' })), { schedule: late }).run, false,
    'at 16:20 the most recent 20:00 anchor is yesterday evening\'s, and this morning\'s run came after it');
  assert.equal(evaluate(['due:daily'], runs(run({ createdAt: '2026-09-08T19:00:00Z', closedAt: '2026-09-08T19:30:00Z' })), { schedule: late }).run, true,
    'a run before yesterday evening\'s anchor leaves this period open');
});

test('a run still open counts — an item that started since the anchor is this period\'s', () => {
  const open = run({ createdAt: '2026-09-09T04:05:00Z', closedAt: null, state: 'open', status: 'task:status:needs-human-failure', park: 'failure', outcome: null });
  assert.equal(evaluate(['due:daily'], runs(open)).run, false);
});

test('a woken item satisfies the cadence terms — the wake IS the cadence', () => {
  const today = run({ createdAt: '2026-09-09T04:05:00Z', closedAt: '2026-09-09T04:30:00Z' });
  const woken = { item: { number: 11, woken: true } };
  assert.equal(evaluate(['due:daily'], runs(today), woken).run, true);

