const nextAnchorFor = (row, now, schedule) => {
  if (row.nextAsk?.at) return ms(row.nextAsk.at);
  if (row.cadence?.kind !== 'due' || !schedule) return null;
  const at = nextAnchor(row.cadence.cadence, schedule, now);
  return at ? ms(at) : null;
};

