// Rewrite every canon task.json: the retired `frequency` becomes the cadence term
// it meant, first in `preconditions`, and a `none` beside it drops — through the
// engine's own serializer, so the file is written exactly as the migration writes one.
import { readFileSync, writeFileSync } from 'node:fs';
import { execSync } from 'node:child_process';
import { serializeTaskDeclaration } from '/home/user/Claudinite/engine/migrations/task-declarations-to-json.mjs';
import { cadenceTermFor } from '/home/user/Claudinite/packs/claudinite-tasks/calendar.mjs';

const files = execSync('git ls-files "packs/*/tasks/*/task.json" "packs/*/queue/tasks/*/task.json"', { cwd: '/home/user/Claudinite' }).toString().trim().split('\n');
for (const f of files) {
  const path = `/home/user/Claudinite/${f}`;
  const raw = JSON.parse(readFileSync(path, 'utf8'));
  if (raw.frequency === undefined) { console.log(`- ${f}: no frequency`); continue; }
  const term = cadenceTermFor(raw.frequency);
  const stated = (raw.preconditions ?? []).filter((e) => String(e).trim() !== 'none');
  const { $schema, frequency, ...rest } = raw;
  const decl = { ...rest, preconditions: stated.includes(term) ? stated : [term, ...stated] };
  const { text } = serializeTaskDeclaration(decl, $schema);
  writeFileSync(path, text);
  console.log(`- ${f}: ${frequency} → ${JSON.stringify(decl.preconditions)}`);
}
