content.content:
1	// The dashboard's derivation layer — repo facts in, view rows out. Pure: it reads
2	// no clock, opens no socket, and touches no DOM, so the whole of what the page
3	// claims is testable in Node and shared verbatim with the browser.
4	//
5	// It states NONE of the queue's vocabulary itself. The label set, the title
6	// grammar, the leash constants and the anchor arithmetic are imported from the
7	// engine modules that define them, which is what makes a dashboard that cannot
8	// drift from the mechanism it renders: there is no second copy to drift.
9	//
10	// Those engine modules are pure ESM with no `node:` imports, which is the property
11	// this file depends on and `browser-graph.test.mjs` pins across the page's whole
12	// import graph. Living inside `packs/claudinite-tasks/` makes the queue modules siblings,
13	// so the dashboard sits beside the mechanism it renders rather than reaching across
14	// the tree at it.
15	//
16	// `stripComments` is the one remaining cross-tree reach, and it is deliberate:
17	// `file-placement` flags it advisory and its own remedy sanctions exactly this case.
18	// Shortening it would mean copying a comment-stripper nearer, and a second stripper
19	// that drifts from the canonical one is worse than the distance.
20	
21	import { stripComments } from '../../engine/checks/helpers/code-scanning.mjs';
22	import { parseTaskDeclaration, applyTaskDefaults } from '../claudinite-tasks/shared-code/task-declaration.mjs';
23	import {
24	  mostRecentAnchor, nextAnchor, periodMs, taskPeriodMs, cadenceOf, cadenceTermFor, holdsOnFailure,
25	  DUE_TERM, ELAPSED_TERM, WOKEN_TERM,
26	} from '../claudinite-tasks/shared-code/anchors.mjs';
27	import {
28	  EXECUTING_LEASH_MS, AGENT_LEASH_MS, STALE_READY_PERIODS, STUCK_BLOCKED_MS,
29	} from '../claudinite-tasks/shared-code/work-items.mjs';
30	import {
31	  WORK_PREFIX, BLOCKED, READY, URGENT, EXECUTING, AGENT,
32	  outcomeOf as decodeOutcome,
33	  STATUS_BLOCKED, STATUS_READY, STATUS_RUNNING_EXECUTOR, STATUS_RUNNING_AGENT,
34	  statusesOn, isParked, parkKindOf, triageLabelFor,
35	  NEEDS_HUMAN_ACTION, NEEDS_HUMAN_DECISION, NEEDS_HUMAN_APPROVAL,
36	  NEEDS_HUMAN_FAILURE, isBlockingPark, parseLastVerdict,
37	  CLAIM_MARKER, HANDOFF_MARKER, EPISODE_MARKER,
38	  parseWorkItemTitle, parseWorkItemBody, taskIdFromPath, hasLabel, labelNames,
39	} from '../claudinite-tasks/shared-code/work-items.mjs';
40	
41	export {
42	  WORK_PREFIX, BLOCKED, READY, URGENT, EXECUTING, AGENT,
43	  EXECUTING_LEASH_MS, AGENT_LEASH_MS, STUCK_BLOCKED_MS, STALE_READY_PERIODS,
44	  parseWorkItemTitle, nextAnchor, mostRecentAnchor, periodMs,
45	};
46	
47	// How long a due item may sit blocked before the page calls the scheduler run out. The scheduler run
48	// is the repo's one cron, hourly; two fires of slack keeps a single late fire from
49	// reading as a fault. Not an engine constant because nothing engine-side measures
50	// this — the scheduler run readies due items on its next fire, whenever that is.
51	export const DUE_SLACK_MS = 2 * 3600e3;
52	
53	const ms = (t) => (t == null ? null : new Date(t).getTime());
54	
55	// --- where a declared pack's tasks live ---------------------------------------
56	
57	// A pack contributes tasks only if the repo DECLARES it: presence on disk is not
58	// activation (core's rule), and the mount carries packs a repo never declared. So
59	// the roster is built from the declaration list, and a task directory belonging to
60	// an undeclared pack is skipped rather than rendered greyed-out.
61	//
62	// Two roots, because the same code reads the canon home and a member: the home
63	// runs from the repo root (`packs/<id>`), a member from the mount
64	// (`.claudinite/shared/packs/<id>`), and a local pack — declared `local/<name>` —
65	// from `.claudinite/local/packs/<name>` in both.
66	export function declaredPackDirs(config) {
67	  const dirs = new Map();
68	  for (const entry of config?.packs ?? []) {
69	    const id = typeof entry === 'string' ? entry : entry?.id;
70	    if (!id) continue;
71	    if (id.startsWith('local/')) {
72	      const name = id.slice('local/'.length);
73	      dirs.set(id, [`.claudinite/local/packs/${name}`]);
74	    } else {
75	      dirs.set(id, [`packs/${id}`, `.claudinite/shared/packs/${id}`]);
76	    }
77	  }
78	  return dirs;
79	}
80	
81	const TASK_PATH_RE = /^(.*)\/tasks\/([^/]+)\/task\.(json|mjs)$/;
82	
83	// Every declared pack's task declarations, from one recursive tree listing.
84	// `paths` is the flat list of blob paths the tree API returned.
85	export function taskDeclarationPaths(paths, config) {
86	  const dirs = declaredPackDirs(config);
87	  const found = [];
88	  for (const path of paths ?? []) {
89	    const m = TASK_PATH_RE.exec(path);
90	    if (!m) continue;
91	    const [, packDir, task] = m;
92	    for (const [pack, roots] of dirs) {
93	      if (roots.includes(packDir)) found.push({ pack, task, path });
94	    }
95	  }
96	  return found.sort((a, b) => `${a.pack}/${a.task}`.localeCompare(`${b.pack}/${b.task}`));
97	}
98	
99	// --- reading a task declaration -----------------------------------------------
100	
101	// The page reads a declaration as TEXT: it renders other repos over the API, where
102	// there is nothing to import and no Node to import it with. A `task.json` parses
103	// whole and takes the contract's defaults for the fields it omits — the same
104	// door the engine's loader runs it through. The retired `task.mjs` is a JS
105	// object literal, so its scalar fields are lifted by pattern over comment-stripped
106	// source — the engine's own `stripComments`, so a `// preconditions: ['due:weekly']`
107	// in a task's header prose can never be mistaken for the declaration.
108	//
109	// A field this cannot read comes back NULL and renders as "unknown". It is never
110	// defaulted: a task whose declaration this misreads must look unreadable, because a
111	// plausible wrong cadence would silently move a next-anchor the whole roster is
112	// read for.
113	// The key must open the line or follow a `{` / `,` — anchoring on the line start
114	// alone would miss a declaration written on one line, and anchoring on nothing
115	// would let `code_work` be found inside `agent_code_work`. The value may close on a
116	// comma, the object's brace, or the line's end, so a last field without a trailing
117	// comma still reads.
118	const at = (field) => `(?:^|[{,])\\s*${field}:\\s*`;
119	
120	const scalar = (src, field) => {
121	  const m = new RegExp(`${at(field)}(?:'([^']*)'|"([^"]*)"|(\\d+)|(true|false))\\s*(?=[,}\\n]|$)`, 'm').exec(src);
122	  if (!m) return null;
123	  if (m[3] !== undefined) return Number(m[3]);
124	  if (m[4] !== undefined) return m[4] === 'true';
125	  return m[1] ?? m[2];
126	};
127	
128	const stringArray = (src, field) => {
129	  const m = new RegExp(`${at(field)}\\[([^\\]]*)\\]`, 'm').exec(src);
130	  if (!m) return null;
131	  return [...m[1].matchAll(/'([^']*)'|"([^"]*)"/g)].map((x) => x[1] ?? x[2]);
132	};
133	
134	// THE FREQUENCY DOOR, as the page runs it (#1725). `frequency` is retired: a task's
135	// cadence is a term in its own `preconditions`. A declaration still carrying the
136	// field — another repo's, read over the API — reads as the cadence term it always
137	// meant, first in the list, with the `none` it used to need beside it dropped; the
138	// field itself does not survive, and nothing downstream reads it. This is the
139	// contract's own rule (`normalizeTaskDeclaration` in `task-contract.mjs`), spelled
140	// again through the same `cadenceTermFor` because that module reaches into `node:`
141	// builtins the page cannot load; `model.test.mjs` runs both over one vector set so
142	// the two cannot drift apart unseen. `manual` reads as `woken`; nothing here writes
143	// either word.
144	const NONE = 'none';
145	function withCadenceTerm(frequency, preconditions) {
146	  if (frequency == null) return preconditions;
147	  const term = cadenceTermFor(frequency);
148	  const stated = (preconditions ?? []).filter((c) => String(c).trim() !== NONE);
149	  return stated.some((c) => String(c).trim() === term) ? stated : [term, ...stated];
150	}
151	
152	// A task may decline to run; whether it CAN is the difference between "did not run"
153	// being routine and being a fault, so the roster shows it. The cadence terms say WHEN
154	// a task runs, not whether, and `none` is the EMPTY precondition — so neither is a
155	// gate, and a task carrying only those answers no here, exactly as it should.
156	const CADENCE_TERM_NAMES = [DUE_TERM, ELAPSED_TERM, WOKEN_TERM];
157	const termName = (t) => t.split(':')[0].trim();
158	const isGate = (entry) => String(entry ?? '').split('||')
159	  .some((t) => termName(t) !== NONE && !CADENCE_TERM_NAMES.includes(termName(t)));
160	const hasGate = (preconditions) => (preconditions ?? []).some(isGate);
161	
162	export function parseDeclaration(text, path = '') {
163	  if (path.endsWith('.json') || /^\s*\{/.test(String(text ?? ''))) return parseJsonDeclaration(text);
164	  const src = stripComments(String(text ?? ''));
165	  // The conditions a task declares. One form, and only one (#1617): the
166	  // `preconditions` expression. A member still stamping the retired
167	  // `precondition_signals` reads as no conditions here, which is what it is —
168	  // a declaration the current engine does not accept.
169	  const preconditions = withCadenceTerm(scalar(src, 'frequency'), stringArray(src, 'preconditions'));
170	  return {
171	    id: scalar(src, 'id'),
172	    agent_model: scalar(src, 'agent_model'),
173	    expected_outcome: scalar(src, 'expected_outcome'),
174	    interrupt_policy: scalar(src, 'interrupt_policy'),
175	    code_work: scalar(src, 'code_work'),
176	    agent_execution_timeout: scalar(src, 'agent_execution_timeout'),
177	    preconditions,
178	    has_precondition: hasGate(preconditions),
179	  };
180	}
181	
182	// The JSON form. The fields the roster reads, and only those, so a declaration
183	// carrying more renders the same as one carrying exactly these. Unparseable text
184	// reads as every field unknown, the same face the module form shows.
185	function parseJsonDeclaration(text) {
186	  let decl;
187	  try {
188	    decl = parseTaskDeclaration(String(text ?? ''));
189	    if (decl !== null && typeof decl === 'object' && !Array.isArray(decl)) applyTaskDefaults(decl);
190	  } catch {
191	    decl = null;
192	  }
193	  if (decl === null || typeof decl !== 'object' || Array.isArray(decl)) decl = {};
194	  const scalarOf = (v) => (['string', 'number', 'boolean'].includes(typeof v) ? v : null);
195	  const stated = Array.isArray(decl.preconditions) && decl.preconditions.every((c) => typeof c === 'string') ? decl.preconditions : null;
196	  const preconditions = withCadenceTerm(scalarOf(decl.frequency), stated);
197	  return {
198	    id: scalarOf(decl.id),
199	    agent_model: scalarOf(decl.agent_model),
200	    expected_outcome: scalarOf(decl.expected_outcome),
201	    interrupt_policy: scalarOf(decl.interrupt_policy),
202	    code_work: scalarOf(decl.code_work),
203	    agent_execution_timeout: scalarOf(decl.agent_execution_timeout),
204	    preconditions,
205	    has_precondition: hasGate(preconditions),
206	  };
207	}
208	
209	// --- a task's cadence ------------------------------------------------------------
210	
211	// What a declaration says about WHEN its task runs, read off its `preconditions` the
212	// way the scheduler reads it (`cadenceOf`), in the roster's terms: one display word,
213	// the period the task keeps, and whether the scheduler asks it at all. Three answers
214	// stay apart — a cadence; NO cadence term, a task asked at every tick that runs on
215	// its other conditions; and UNREADABLE, conditions this could not lift — because a
216	// parse failure shown as "on movement" would hide behind a legitimate answer.
217	//
218	// Only a `due:` cadence is on the calendar, so only it can have a next anchor: an
219	// elapsed cadence counts from the task's newest run, and `woken` and no-cadence have
220	// no next instant at all. `scheduled` is null, not false, where nothing was read.
221	//
222	// `holdsOnFailure` is the same read for the one other thing a declaration says about
223	// its own lane: whether a failure park stops the task (`last-run-not-failed`). No
224	// park holds a lane by itself, so a failure the declaration does not name is a break
225	// to diagnose beside a task still being asked on schedule.
226	export function describeCadence(preconditions) {
227	  if (!Array.isArray(preconditions)) {
228	    return { frequency: null, cadence: null, periodMs: null, scheduled: null, holdsOnFailure: null, anchorNote: 'cadence unknown' };
229	  }
230	  const cadence = cadenceOf(preconditions);
231	  const period = taskPeriodMs({ preconditions });
232	  const holds = holdsOnFailure(preconditions);
233	  if (cadence?.kind === 'woken') {
234	    return { frequency: WOKEN_TERM, cadence, periodMs: period, scheduled: false, holdsOnFailure: holds, anchorNote: 'woken — only an item somebody created' };
235	  }
236	  if (cadence === null) {
237	    return { frequency: 'on movement', cadence, periodMs: period, scheduled: true, holdsOnFailure: holds, anchorNote: 'no cadence term — asked at every tick' };
238	  }
239	  if (cadence.kind === 'elapsed') {
240	    return {
241	      frequency: `every ${cadence.text}`, cadence, periodMs: period, scheduled: true, holdsOnFailure: holds,
242	      anchorNote: `every ${cadence.text} — counted from its newest run, not the calendar`,
243	    };
244	  }
245	  return { frequency: cadence.cadence, cadence, periodMs: period, scheduled: true, holdsOnFailure: holds, anchorNote: null };
246	}
247	
248	// --- work items ----------------------------------------------------------------
249	
250	// An item is a filed `[claudinite-work]` issue OR an adopted marked issue — the
251	// one-issue request model's other shape, which keeps the person's own title
252	// (tasks-dispatch DESIGN §16.1). One definition, shared with the queue's own reader.
253	export { isQueueItem as isWorkItem } from '../claudinite-tasks/shared-code/work-items.mjs';
254	
255	// THE PAGE'S FIVE STATE KEYS. Four are the engine's own status labels; the fifth is
256	// this page's own word, because a park is four labels and the page groups them into
257	// one column, routing by kind separately (`triageOf`). It is a display key and never
258	// a label: nothing writes `parked` to an issue.
259	const STATE_KEY = new Map([
260	  [STATUS_BLOCKED, BLOCKED], [STATUS_READY, READY],
261	  [STATUS_RUNNING_EXECUTOR, EXECUTING], [STATUS_RUNNING_AGENT, AGENT],
262	]);
263	
264	// The one state an open item is in, decoded from whatever spelling filed it, or
265	// `unlabelled` for an item wearing none — which is not a display quirk but the
266	// torn-label-swap leavings the janitor repairs, so it gets its own rendered state
267	// rather than being folded into "blocked".
268	export const PARKED = 'parked';
269	
270	export function stateOf(item) {
271	  if (item?.state === 'closed') return 'closed';
272	  if (isParked(item)) return PARKED;
273	  const worn = statusesOn(item).filter((s) => STATE_KEY.has(s));
274	  if (worn.length === 1) return STATE_KEY.get(worn[0]);
275	  if (worn.length > 1) return 'torn';
276	  return 'unlabelled';
277	}
278	
279	// What the park is asking for, or null for an item that is not parked. A park whose
280	// kind cannot be decoded — an older engine's bare one, a word a newer engine
281	// invented — reads as `failure`, the lane that says "someone diagnose this".
282	export const triageOf = (item) => (isParked(item) ? triageLabelFor(parkKindOf(item)) : null);
283	
284	const TRIAGE_TEXT = {
285	  [NEEDS_HUMAN_APPROVAL]: 'a PR to approve',
286	  [NEEDS_HUMAN_ACTION]: 'something to change outside the code',
287	  [NEEDS_HUMAN_DECISION]: 'a decision to make',
288	  [NEEDS_HUMAN_FAILURE]: 'a break to diagnose',
289	};
290	
291	// The outcome as its canonical word ('done' | 'delivered' | 'obsolete' | null) —
292	// the engine's decoder, which maps every legacy spelling straight to today's.
293	export const outcomeOf = decodeOutcome;
294	
295	// How long the item has sat where it is. Every transition is a label write, so
296	// `updated_at` is the last touch — the same quantity the janitor's rules count.
297	const idleMs = (item, now) => ms(now) - (ms(item?.updated_at) ?? ms(item?.created_at) ?? ms(now));
298	
299	// Warnings, each mirroring a real recovery rule rather than a display heuristic, so
300	// what the page flags is what the engine will actually act on — and how long the
301	// viewer waits for it.
302	//
303	// `isOpen(number)` answers whether a `Blocked-by` issue is still open — true, false,
304	// or null for one outside what the caller fetched. Unknown is never alarmed on.
305	export function warningsFor(item, now, { periodFor = () => null, isOpen = () => null } = {}) {
306	  const out = [];
307	  const state = stateOf(item);
308	  const idle = idleMs(item, now);
309	  if (state === EXECUTING && idle >= EXECUTING_LEASH_MS) {
310	    out.push({ level: 'serious', text: 'executing past the leash — the next scheduler run reclaims it' });
311	  }
312	  if (state === AGENT && idle >= AGENT_LEASH_MS) {
313	    out.push({ level: 'serious', text: 'agent claim past the leash — the janitor reclaims it' });
314	  }
315	  if (state === READY) {
316	    const per = periodFor(`${parseWorkItemTitle(item.title)?.pack}/${parseWorkItemTitle(item.title)?.task}`) ?? 86400e3;
317	    if (idle >= STALE_READY_PERIODS * per) out.push({ level: 'serious', text: 'ready but unpicked for ~2 periods' });
318	  }
319	  if (state === BLOCKED) {
320	    // The standing-item model: blocked is the queue's healthy quiet state, not a
321	    // fault. A rolled item waiting out its Not-before never warns; what does warn is
322	    // the two things the engine would actually act on — dependencies unresolved past
323	    // the janitor's threshold, and an item DUE that the scheduler run has failed to ready.
324	    const { notBefore, blockedBy } = parseWorkItemBody(item.body);
325	    const wake = ms(notBefore);
326	    const depStates = blockedBy.map((n) => isOpen(n));
327	    if (wake !== null && wake > ms(now)) {
328	      // waiting out its stamped wake — healthy, whatever its age
329	    } else if (depStates.some((s) => s === true)) {
330	      if (idle >= STUCK_BLOCKED_MS) {
331	        out.push({ level: 'warning', text: `blocked on ${blockedBy.map((n) => `#${n}`).join(', ')} for over 2 days — the janitor flags stuck dependencies` });
332	      }
333	    } else if (!depStates.some((s) => s === null)) {
334	      // Nothing blocks it any more: the next scheduler run readies it. Due only measures from
335	      // the stamped wake — with dependencies the closing time is not on this item,
336	      // and a guess would alarm on an item that became due minutes ago.
337	      if (wake !== null && ms(now) - wake >= DUE_SLACK_MS) {
338	        out.push({ level: 'serious', text: 'due but not readied — is the scheduler run running?' });
339	      } else if (wake === null && blockedBy.length === 0 && idle >= DUE_SLACK_MS) {
340	        out.push({ level: 'serious', text: 'due but not readied — is the scheduler run running?' });
341	      }
342	    }
343	  }
344	  if (state === PARKED) {
345	    // What the park is asking for — an approval waiting on a reviewer is not the
346	    // same alarm as a broken run. Whether the break also holds the task's lane is
347	    // the declaration's word, not the park's, and the roster's next ask says it.
348	    const t = triageOf(item);
349	    out.push({
350	      level: isBlockingPark(item) ? 'critical' : 'warning',
351	      text: t ? `parked for a human — ${TRIAGE_TEXT[t]}` : 'parked for a human — unclassified',
352	    });
353	  }
354	  if (state === 'torn') out.push({ level: 'warning', text: 'wearing more than one state label' });
355	  if (state === 'unlabelled') out.push({ level: 'warning', text: 'open with no state label' });
356	  return out;
357	}
358	
359	// An open item, decorated with everything the queue lane renders.
360	export function describeItem(item, now, opts = {}) {
361	  // A marked issue keeps the person's own title, so its task comes from the worker
362	  // path its machine block names — without that the page would render every request
363	  // run as an item belonging to no task at all.
364	  const parsed = parseWorkItemTitle(item.title)
365	    ?? (taskIdFromPath(parseWorkItemBody(item.body).taskPath) ? { ...taskIdFromPath(parseWorkItemBody(item.body).taskPath), qualifier: null } : null)
366	    ?? { pack: null, task: null, qualifier: null };
367	  const body = parseWorkItemBody(item.body);
368	  const state = stateOf(item);
369	  return {
370	    number: item.number,
371	    // The issue's own title, kept as GitHub has it: a surface that NAMES one item —
372	    // rather than counting them — has nothing else to call it by.
373	    title: item.title,
374	    key: parsed.pack && parsed.task ? `${parsed.pack}/${parsed.task}` : null,
375	    ...parsed,
376	    state,
377	    outcome: outcomeOf(item),
378	    triage: triageOf(item),
379	    blockingPark: state === PARKED && isBlockingPark(item),
380	    urgent: hasLabel(item, URGENT),
381	    labels: labelNames(item),
382	    notBefore: body.notBefore,
383	    blockedBy: body.blockedBy,
384	    taskPath: body.taskPath,
385	    // When somebody created or force-woke this item, or null for one the scheduler filed.
386	    woken: body.woken ?? null,
387	    // The roll's record: when the last ask declined, why, and the stamped wake.
388	    lastVerdict: parseLastVerdict(item.body),
389	    createdAt: item.created_at,
390	    updatedAt: item.updated_at,
391	    closedAt: item.closed_at ?? null,
392	    idleMs: idleMs(item, now),
393	    comments: item.comments ?? 0,
394	    warnings: warningsFor(item, now, opts),
395	  };
396	}
397	
398	// --- the roster ----------------------------------------------------------------
399	
400	// One row per DECLARED task, whether or not it has ever run — a task that has never
401	// produced an item is exactly the interesting case, and an issue-derived list would
402	// omit it entirely.
403	export function buildRoster({ tasks = [], items = [], now, schedule, isOpen }) {
404	  const byKey = new Map();
405	  for (const it of items) {
406	    const p = parseWorkItemTitle(it.title);
407	    if (!p) continue;
408	    const key = `${p.pack}/${p.task}`;
409	    if (!byKey.has(key)) byKey.set(key, []);
410	    byKey.get(key).push(it);
411	  }
412	
413	  return tasks.map((t) => {
414	    const key = `${t.pack}/${t.task}`;
415	    const mine = (byKey.get(key) ?? []).slice()
416	      .sort((a, b) => ms(b.created_at) - ms(a.created_at));
417	    const open = mine.filter((i) => i.state === 'open');
418	    const closed = mine.filter((i) => i.state === 'closed');
419	    const read = describeCadence(t.declaration?.preconditions);
420	
421	    // The calendar answers only a `due:` cadence, and only where the repo has a
422	    // schedule to anchor it on; every other reading carries its own note instead, so
423	    // an unreadable declaration yields no anchor rather than a guessed one.
424	    let next = null;
425	    let anchorNote = read.anchorNote;
426	    if (read.cadence?.kind === 'due') {
427	      if (!schedule) anchorNote = 'no schedule configured';
428	      else next = nextAnchor(read.cadence.cadence, schedule, now);
429	    }
430	
431	    const current = open.length
432	      ? describeItem(open[0], now, { periodFor: () => read.periodMs, isOpen })
433	      : null;
434	
435	    return {
436	      key,
437	      pack: t.pack,
438	      task: t.task,
439	      path: t.path,
440	      declaration: t.declaration ?? null,
441	      frequency: read.frequency,
442	      cadence: read.cadence,
443	      scheduled: read.scheduled,
444	      holdsOnFailure: read.holdsOnFailure,
445	      nextAnchor: next,
446	      anchorNote,
447	      periodMs: read.periodMs,
448	      current,
449	      nextAsk: nextAskOf(current, next, anchorNote, read.holdsOnFailure),
450	      openCount: open.length,
451	      lastClosed: closed.length ? describeItem(closed[0], now) : null,
452	      history: closed.map((i) => describeItem(i, now)),
453	    };
454	  });
455	}
456	
457	// What will actually happen to this task next, derived from the standing item where
458	// one exists — the calendar answers only when no item does (the next instantiation).
459	// This is where the standing-item model's facts become the roster's advice:
460	//   - the stamped Not-before IS the schedule (DESIGN §14, S28), so it wins over the
461	//     computed anchor;
462	//   - a failure park holds the task's lane only where the declaration says so with
463	//     `last-run-not-failed` (§5) — showing an anchor there would promise a run the
464	//     task itself declines, and showing `held` anywhere else would hide a run the
465	//     scheduler files on schedule around the park;
466	//   - every other park consumed its occurrence and leaves the lane open, so the
467	//     next anchor stands beside it.
468	function nextAskOf(current, anchor, anchorNote, holdsOnFailure) {
469	  if (!current) return anchor ? { kind: 'anchor', at: anchor } : { kind: 'note', note: anchorNote };
470	  if (current.state === READY) return { kind: 'ready', urgent: current.urgent };
471	  if (current.state === EXECUTING || current.state === AGENT) {
472	    return { kind: 'running', phase: current.state === AGENT ? 'agent' : 'executor' };
473	  }
474	  if (current.state === PARKED) {
475	    if (current.blockingPark && holdsOnFailure === true) return { kind: 'held' };
476	    return anchor ? { kind: 'anchor', at: anchor } : { kind: 'note', note: anchorNote };
477	  }
478	  if (current.state === BLOCKED) {
479	    if (current.notBefore) return { kind: 'wake', at: new Date(current.notBefore) };
480	    return current.blockedBy.length ? { kind: 'deps', on: current.blockedBy } : { kind: 'ready-soon' };
481	  }
482	  // torn / unlabelled — off the state machine until the janitor repairs it.
483	  return { kind: 'off-machine' };
484	}
485	
486	// --- what is about to happen ------------------------------------------------------
487	
488	// The next 24 hours as UTC hour buckets, each carrying the task rows whose next ask
489	// lands in it. The strip this draws answers a question no single row can: whether the
490	// day's scheduled work is spread out or piled into one hour.
491	//
492	// FLEET OR REPO, the same reduction: the caller hands in whatever roster rows it has,
493	// one member's or every member's, and a row carries the repo it came from where that
494	// matters.
495	//
496	// A `held` next ask is placed at NOW and marked critical rather than left out. A task
497	// whose blocking park stops it being scheduled at all has no future anchor, and
498	// dropping it would draw the emptiest strip on the worst-off repo — the one case where
499	// an empty hour must not read as a quiet one.
500	export const WAKE_STRIP_HOURS = 24;
501	
502	export function wakeStrip(rows, now, { hours = WAKE_STRIP_HOURS } = {}) {
503	  const start = new Date(now);
504	  start.setUTCMinutes(0, 0, 0);
505	  const key = (t) => new Date(t).toISOString().slice(0, 13);
506	  const buckets = Array.from({ length: hours }, (_, i) => ({
507	    hour: key(start.getTime() + i * 3600e3),
508	    tasks: [],
509	    held: 0,
510	  }));
511	  const byHour = new Map(buckets.map((b) => [b.hour, b]));
512	
513	  for (const row of rows ?? []) {
514	    const ask = row?.nextAsk;
515	    if (!ask) continue;
516	    const held = ask.kind === 'held';
517	    // Only the two kinds that name a MOMENT land on a strip of hours: an anchor (the
518	    // calendar's next fire) and a wake (a stamped Not-before, which IS the schedule).
519	    // `ready`, `running` and `deps` are happening or waiting on something other than
520	    // the clock, and belong to the row rather than to a future hour.
521	    const at = held ? start.getTime() : (ask.kind === 'anchor' || ask.kind === 'wake' ? ms(ask.at) : null);
522	    if (at === null) continue;
523	    const bucket = byHour.get(key(at));
524	    if (!bucket) continue;                      // past the strip's far end — not this day's business
525	    bucket.tasks.push({ key: row.key, repo: row.repo ?? null, held });
526	    if (held) bucket.held += 1;
527	  }
528	
529	  const peak = buckets.reduce((n, b) => Math.max(n, b.tasks.length), 0);
530	  return { from: buckets[0]?.hour ?? null, hours: buckets, peak };
531	}
532	
533	// Outcome tallies over the closed items the scan actually saw. `scanned` travels
534	// with them: every count here is over a window, and a window is not "all of it".
535	export function outcomeTally(rows) {
536	  const t = { done: 0, delivered: 0, obsolete: 0, none: 0 };
537	  for (const r of rows) for (const h of r.history) t[h.outcome ?? 'none'] += 1;
538	  return t;
539	}
540	
541	// --- the protocol comments ------------------------------------------------------
542	
543	// Which of the three markers a comment carries. The markers are HTML comments so a
544	// human reading the issue sees prose; the page shows the protocol beat instead.
545	export function commentKind(body) {
546	  const b = String(body ?? '');
547	  if (b.includes(EPISODE_MARKER)) return 'episode';
548	  if (b.includes(HANDOFF_MARKER)) return 'handoff';
549	  if (b.includes(CLAIM_MARKER)) return 'claim';
550	  return null;
551	}
